    /**
     * Output starvations, total since the device started.
     */
    val starvation: Long?,
)

/**
 * A device's newest change in [`HubHealth`]: the newest history record of a
 * write, recall, import, schedule run or new firmware.
 */
data class HubLastChange(
    /**
     * When (ISO-8601 UTC).
     */
