    /**
     * The notice row of the code (`dlink.<code>`, `image_refused`, ...);
     * "" without a code (then the step's row says it).
     */
    val noticeKey: String,
)

/**
 * One device of a rollout.
 */
data class HubRolloutDevice(
    /**
     * The device.
     */
    val serial: String,
    /**
     * `pending`, `running`, `ok`, `failed`, `cancelled`, `not_tried`.
     */
    val state: String,
    /**
     * The step it is at or ended at ("" before its first).
     */
    val step: String,
    /**
     * The steps done, in order.
     */
    val steps: List<HubRolloutStep>,
    /**
     * Before its flash.
     */
    val before: HubRolloutBefore?,
    /**
     * After it came back.
     */
    val after: HubRolloutAfter?,
    /**
     * Why it failed.
     */
    val failed: HubRolloutFailed?,
)

/**
 * A rollout ([`DspiCore::hub_rollouts`], `fw.rollout.changed`).
 */
data class HubRollout(
    /**
     * The hub's id (`ro1`, ...; never reused).
     */
    val id: String,
    /**
     * The serial, or `group:<id>`.
     */
    val target: String,
    /**
     * The image's name.
     */
    val image: String,
    /**
     * Its SHA-256.
     */
    val imageSha256: String,
    /**
     * Its DSPi version.
     */
    val imageVersion: String,
    /**
     * The Admin's client name.
     */
    val by: String,
    /**
     * Started without the mute check.
     */
    val whileLive: Boolean,
    /**
     * `running`, `ok`, `failed`, `cancelled`.
     */
    val state: String,
    /**
     * ISO-8601 UTC.
     */
    val startedAt: String,
    /**
     * ISO-8601 UTC; "" while running.
     */
    val endedAt: String,
    /**
     * One entry per device, in order.
     */
    val devices: List<HubRolloutDevice>,
)

/**
 * What [`DspiCore::hub_inventory_forget`] removed.
 */
data class HubInventoryForgot(
    /**
     * The device.
     */
    val serial: String,
    /**
     * What went, in order: `record`, then `events` if it had history files,
     * then `snapshots` if asked and it had any.
     */
    val forgot: List<String>,
)

/**
 * A measurement document on the hub with its text
 * ([`DspiCore::hub_measure_doc_get`]).
 */
data class HubMeasureDocument(
    /**
     * Its entry on the hub.
     */
    val doc: MeasureDocInfo,
    /**
     * The document's text (compact JSON), read and checked by its kind's
     * reader.
     */
    val document: String,
)

/**
 * A document filed on the hub ([`DspiCore::hub_measure_doc_put`]).
 */
data class HubMeasureDocPut(
    /**
     * Its entry on the hub.
     */
    val doc: MeasureDocInfo,
    /**
     * False: the hub already held this document with the same content.
     */
    val created: Boolean,
)

/**
 * One row of the merged list ([`DspiCore::measure_docs_merged`]).
 */
data class MergedMeasureDoc(
    /**
     * The entry: the hub's where it holds the id (the hub's wins).
     */
    val doc: MeasureDocInfo,
    /**
     * [`super::WHERE_LOCAL`], [`super::WHERE_HUB`] or [`super::WHERE_BOTH`]
     * (`where` in JSON).
     */
    val location: String,
    /**
     * This console's own copy of an id the hub holds with different
     * content: listed beside the hub's, never overwritten by it.
     */
    val localCopy: Boolean,
)

/**
 * The documents of both sides ([`DspiCore::measure_docs_merged`]).
 */
data class MeasureDocsMerged(
    /**
     * By kind (measurement, mic, target), then oldest first; on an id both
     * sides hold with different content the hub's row comes first, then the
     * local copy.
     */
    val entries: List<MergedMeasureDoc>,
    /**
     * The hub's list is in it (a hub with `hub_measure` answered).
     */
    val hubListed: Boolean,
    /**
     * Why the hub's list is not in it, as a notice row; "" when it is, or
     * when there is no such hub.
     */
    val hubNoticeKey: String,
)

/**
 * One change in the history ([`DspiCore::history`]).
 */
data class HistoryEntry(
    /**
     * The registry path (`out.gain`, `eq.freq`, ...), or one of the
     * journal's own: `eq.band` (a whole band: type, bypass, then freq, Q,
     * gain and the Linkwitz target Q as little-endian `f32`s), `ext.pairmap`
     * (the crossfeed pair map's four bytes), `ext.vreg` (a core-voltage
     * request: op and value), `raw` (a raw request: opcode and `wValue` as
     * indices, the payload as the value), `ext.alink.slots` (the 8
     * slot bytes), `ext.alink.phase` (mode, then the delay and the
     * hops offset as little-endian 16-bit values), `ext.alink.apply`
     * (op and arg as indices, the 16-byte request as the value) and
     * `ext.alink.stats_reset`. A control-surface operation is
     * under its `cs.*` path with the operation's JSON as text.
     */
    val path: String,
    /**
     * The path's indices (an output, a channel and a band, ...).
     */
    val indices: List<Int>,
    /**
     * The value before, when known; undo writes it back.
     */
    val before: ParamValue?,
    /**
     * The value after (`trigger` for an action).
     */
    val after: ParamValue,
    /**
     * Who made it.
     */
    val source: HistorySource,
    /**
     * When, in milliseconds since the Unix epoch (a drag: its last step).
     */
    val atMs: Long,
    /**
     * Whether undo may reverse it. The registry decides: only a parameter
     * with no hazard (not a flash write, an audible one, a reconfiguration,
     * a deferred or an irreversible one).
     */
    val undoable: Boolean,
    /**
     * The undo group's label ([`DspiCore::begin_group`]) when the change
     * was written inside one; `None` otherwise.
     */
    val label: String?,
    /**
     * The change's id, for [`DspiCore::revert_entry`]: unique in the
     * process, the same for every value of one step.
     */
    val id: Long,
    /**
     * Who made it: 0 for this app itself, another number for an actor the
     * app registered (an AI agent, `crate::actor`).
     */
    val actor: Long,
    /**
     * The actor's label ("AI · Claude Code"); `None` for this app itself.
     */
    val actorLabel: String?,
)

/**
 * What [`DspiCore::undo`] or [`DspiCore::redo`] did.
 */
data class HistoryMove(
    /**
     * The change reversed (undo) or applied again (redo); `None` when
     * nothing moved.
     */
    val entry: HistoryEntry?,
    /**
     * The changes stepped over on the way, newest first, which cannot be
     * undone (see [`HistoryEntry::undoable`]). An entry here that is
     * undoable had no value before to restore, or someone else has changed
     * it since (`note` says who); the walk stopped there. A drag's step of
     * several values lists here each value someone else changed since, one
     * entry each, also when its other values moved.
     */
    val skipped: List<HistoryEntry>,
    /**
     * Why a value was left alone, in words, when another writer changed it
     * since (only where the core leaves such a change alone): nothing moved,
     * or, for a drag's step of several values, the others did. After an
     * undo of "Protect all outputs" it also says the limiters stay on
     * ([`PROTECT_UNDONE_NOTE`], WP P1EFIX). `None` otherwise.
     */
    val note: String?,
)

/**
 * The open device's limits ([`DspiCore::limits_status`]).
 */
data class LimitsStatus(
    /**
     * A profile is in force for the open device.
     */
    val active: Boolean,
    /**
     * The open device's serial ("" with none).
     */
    val serial: String,
    /**
     * How the profile was found: `none`, `ok`, `fell_back` (the profile
     * file is missing or unreadable; the last good copy is in force) or
     * `unreadable` (no good copy: running unlimited).
     */
    val state: String,
    /**
     * The standing notice's key (`limits.fell_back`, `limits.unreadable`;
     * `crate::notice_text`), "" when there is none to show.
     */
    val noticeKey: String,
    /**
     * Why, for the notice's detail line.
     */
    val detail: String,
    /**
     * What the last clamp held (an import, a recall, a profile applied, a
     * slot load), one row each, in the import's words.
     */
    val lastHeld: List<String>,
)

/**
 * What applying a profile did ([`DspiCore::limits_apply_profile`]).
 */
data class LimitsApply(
    /**
     * The report: "Held to the limits profile: ..." when the device was
     * outside a narrowed limit, nothing otherwise.
     */
    val lines: List<String>,
    /**
     * What moved, one row each.
     */
    val held: List<String>,
    /**
     * Writes that failed, and why (the profile is kept all the same).
     */
    val notes: List<String>,
)

/**
 * One limits field's range, for a client's limits editor
 * ([`limits_field_ranges`]).
 */
data class LimitFieldRange(
    /**
     * The profile document's field: `maxGainDb`, `limiterCeilingDb`,
     * `highpassMinHz`, `highpassMinSlopeDb`, `delayMinMs`, `delayMaxMs`
     * (each output's), `maxPeqBoostDb`, `masterVolumeMaxDb` (the device's).
     */
    val key: String,
    /**
     * A field of each output's limits.
     */
    val perOutput: Boolean,
    /**
     * `dB`, `dBFS`, `Hz`, `dB/oct` or `ms`.
     */
    val unit: String,
    /**
     * The lowest value the profile keeps.
     */
    val min: Float,
    /**
     * The highest value the profile keeps.
     */
    val max: Float,
    /**
     * The editor's step.
     */
    val step: Float,
)

/**
 * The open device's installer lock on this console
 * ([`DspiCore::installer_lock_state`]).
 */
data class LockState(
    /**
     * The open device's serial ("" with none).
     */
    val serial: String,
    /**
     * An installer PIN is set for it on this console (an unreadable PIN
     * file counts as set; `detail` says why).
     */
    val pinSet: Boolean,
    /**
     * A PIN is set and this console is unlocked for the device, this
     * session.
     */
    val unlocked: Boolean,
    /**
     * The locked-user state: a PIN is set, the lock covers something and
     * this console is not unlocked. Only `allowed_writes` pass.
     */
    val locked: Boolean,
    /**
     * The Installer pages, the profile and the PIN may change without a
     * PIN prompt: no PIN is set, or the console is unlocked.
     */
    val installerOpen: Boolean,
    /**
     * What the lock covers: the mode manifest's screen ids (the profile's
     * `lockedPages`); empty: a PIN alone locks nothing.
     */
    val covers: List<String>,
    /**
     * The writes the locked-user state allows (registry paths).
     */
    val allowedWrites: List<String>,
    /**
     * Wrong PINs since the last good one.
     */
    val wrongTries: Long,
    /**
     * How long until the next attempt is allowed, ms; 0: now.
     */
    val retryAfterMs: Long,
    /**
     * Unlocked with the recovery code: the installer should set a new PIN.
     */
    val recovered: Boolean,
    /**
     * The installer's note, for the locked front page.
     */
    val note: String,
    /**
     * How to reach the installer.
     */
    val contact: String,
    /**
     * The notice the unlock dialog shows in one line: the lock is on this
     * console, the DSPi itself is open (`installer_lock.scope`); or, when
     * the hub holds it, the hub's PIN unlocks it (`installer_lock.hub`).
     */
    val scopeNoticeKey: String,
    /**
     * Why the PIN's file is unreadable, when it is.
     */
    val detail: String,
    /**
     * Which lock this is: `console` (this console's PIN), `hub` (the DSPi
     * Link hub the device is reached through holds the PIN; unlocking asks
     * the hub), or "" with no PIN. One lock, one prompt.
     */
    val heldBy: String,
    /**
     * The mode the hub pins for this console's role on this device
     * (`mode.pinned`), "" for none.
     */
    val hubPinnedMode: String,
)

/**
 * A PIN just set ([`DspiCore::installer_pin_set`]).
 */
data class InstallerPin(
    /**
     * The recovery code (`XXXXX-XXXXX-XXXXX-XXXXX`): shown this once, for
     * the hand-over note, never kept but as a hash (notice
     * `installer_lock.recovery`).
     */
    val recoveryCode: String,
    /**
     * The lock now.
     */
    val state: LockState,
)

/**
 * What to tell the user about a [`LinkPhase`].
 */
data class LinkPhaseText(
    /**
     * Stable key of `text`, for localising: `no_device`, `needs_pairing.fixed`.
     */
    val key: String,
    /**
     * The phase's name ([`link_phase_key`]), also for an entry split by
     * `pin_source`.
     */
    val phase: String,
    /**
     * The English.
     */
    val text: String,
    /**
     * Stable key of `action`, if the phase has a button of its own.
     */
    val actionKey: String?,
    /**
     * The English of that button.
     * [`LinkPhase::Reconnecting`] has one, which calls `link_close`: the owner's
     * rule is that a lost connection always offers the way out.
     */
    val action: String?,
)

/**
 * One output to measure.
 */
data class MeasureOutput(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * Its way.
     */
    val role: MeasureRole,
    /**
     * The speaker it belongs to (`L`, `R`, `Sub`), for the document.
     */
    val speaker: String,
    /**
     * Its alignment group: the outputs of one group are measured in one
     * walked run (PLAN-P5 section 1.4 step 4). Ignored by the other kinds.
     */
    val group: Int,
    /**
     * A summed run plays this output inverted (its net programme polarity).
     */
    val inverted: Boolean,
)

/**
 * What to measure and how (`measure_preflight`, `measure_start`). Every
 * number 0 (or absent) is the plan's default.
 */
data class MeasureSetup(
    /**
     * The run kind.
     */
    val kind: MeasureRunKind,
    /**
     * The outputs, 1 to 16, each once.
     */
    val outputs: List<MeasureOutput>,
    /**
     * Where the microphone is.
     */
    val placement: MeasurePlacement,
    /**
     * Positions (3 to 9, multi-position) or reseats (1 to 9, headphones).
     */
    val count: Int,
    /**
     * The coupler, for headphones.
     */
    val coupler: MeasureCoupler?,
    /**
     * The microphone's `mic` document's text; "" for an uncalibrated
     * microphone (relative dB, no SPL cap).
     */
    val micDocument: String,
    /**
     * One sweep, ms (1000 to 15000; 0: 5500, 2700 for a live sweep).
     */
    val sweepMs: Long,
    /**
     * The gap after each cycle, ms (300 to 2000; 0: 1000 for speakers, 300
     * on a coupler).
     */
    val gapMs: Long,
    /**
     * Passes of a walked run (2 to 8; 0: 3).
     */
    val passes: Int,
    /**
     * Pink noise, ms (1000 to 60000; 0: 10000).
     */
    val pinkMs: Long,
    /**
     * The generator's ceiling, peak dBFS: lower than the mode's default, or
     * higher up to the hard cap (-6 speakers, -20 headphones).
     */
    val ceilingDb: Float?,
    /**
     * The SPL cap with a calibrated microphone, dB SPL (default 95 speakers,
     * 90 on a coupler; at most 105 and 100).
     */
    val splCapDb: Float?,
    /**
     * The capture's rate, Hz (0: 48000).
     */
    val captureRateHz: Long,
    /**
     * The document's name ("" names it by the date).
     */
    val name: String,
    /**
     * Play at the start level only (-50 dBFS speakers, -60 dBFS headphones):
     * the ceiling is the start level, so the ramp never goes above it; every
     * other rule unchanged (P5SPIKE's timing test).
     */
    val startLevelOnly: Boolean,
    /**
     * Take each output's role, speaker and group from the device's stored
     * speaker layout instead of `outputs` (MPLAN 2.2, `roles: "layout"`);
     * with no outputs listed, every output of the layout. Refused
     * (`measure.layout_unconfirmed`) while the user has not confirmed the
     * layout.
     */
    val rolesFromLayout: Boolean,
)

/**
 * A walked run's timing (PLAN-P5 section 1.1 steps 6 and 7): the clock fit,
 * every cycle's residual and the quality gate's verdict. Non-finite numbers
 * read 0.
 */
data class MeasureTiming(
    /**
     * The run passed the timing quality gate.
     */
    val reliable: Boolean,
    /**
     * The microphone's clock against the DSPi's, ppm.
     */
    val ratioPpm: Double,
    /**
     * The clock ratio was fitted (two passes or more).
     */
    val ratioFitted: Boolean,
    /**
     * The largest cycle residual, µs.
     */
    val maxResidualUs: Double,
    /**
     * The residual bound the run was held to, µs.
     */
    val residualBoundUs: Double,
    /**
     * The largest phase disagreement between repeats, degrees.
     */
    val maxPhaseSpreadDeg: Double,
    /**
     * Passes in the run.
     */
    val passes: Int,
    /**
     * Why not reliable, in words (empty when reliable).
     */
    val reasons: List<String>,
    /**
     * Each cycle's output, in run order.
     */
    val cycleOutputs: List<Int>,
    /**
     * Each cycle's residual from the fit, µs, in run order.
     */
    val cycleResidualsUs: List<Double>,
)

/**
 * One preflight finding: a notice key and its words.
 */
data class MeasureIssue(
    /**
     * The notice key (`notice_for_key`), e.g. `measure.volume_high`.
     */
    val key: String,
    /**
     * The output it is about, if one.
     */
    val output: Int?,
    /**
     * What it is, in words (English; the key localises).
     */
    val message: String,
)

/**
 * What stands between the setup and a measurement (PLAN-P5 section 1.2).
 */
data class MeasurePreflight(
    /**
     * Nothing blocks: `measure_start` may play.
     */
    val clear: Boolean,
    /**
     * Every blocker, in words; nothing is played until they are clear.
     */
    val blockers: List<MeasureIssue>,
    /**
     * What does not block but the user should know.
     */
    val warnings: List<MeasureIssue>,
)

/**
 * One output's ramp result.
 */
data class MeasureLevel(
    /**
     * The output.
     */
    val output: Int,
    /**
     * The generator's peak level the ramp settled on, dBFS.
     */
    val levelDb: Float,
)

/**
 * A session's state: what the screens show and what the client must do.
 */
data class MeasureState(
    /**
     * Where it stands.
     */
    val phase: MeasurePhase,
    /**
     * The run kind.
     */
    val kind: MeasureRunKind,
    /**
     * The session holds the generator or the lock: Stop is shown.
     */
    val active: Boolean,
    /**
     * The client must push capture now (from the pre-roll to the end).
     */
    val wantsCapture: Boolean,
    /**
     * The capture rate the session expects, Hz.
     */
    val captureRateHz: Long,
    /**
     * The position (or reseat) being measured, 1-based.
     */
    val position: Int,
    /**
     * Positions (or reseats) in all.
     */
    val positions: Int,
    /**
     * The run being measured, 1-based.
     */
    val run: Int,
    /**
     * Runs in all.
     */
    val runs: Int,
    /**
     * The output now ramping or playing alone, if one.
     */
    val output: Int?,
    /**
     * The generator's level now, peak dBFS, while it plays.
     */
    val levelDb: Float?,
    /**
     * The ramps' results so far (this run).
     */
    val rampLevels: List<MeasureLevel>,
    /**
     * The run's level (the minimum of its ways' ramp levels).
     */
    val runLevelDb: Float?,
    /**
     * Frames pushed since the session began.
     */
    val frames: Long,
    /**
     * The capture frame at which the latest START was acknowledged.
     */
    val generatorStartFrame: Long?,
    /**
     * STARTs sent in this session (a client's simulated microphone renders
     * each one).
     */
    val generatorStarts: Long,
    /**
     * The current phase's progress, 0 to 1.
     */
    val progress: Float,
    /**
     * Why it stopped, or what it asks.
     */
    val issue: MeasureIssue?,
    /**
     * The last run passed the timing quality gate (walked runs).
     */
    val timingReliable: Boolean?,
    /**
     * `measure_result` has a document.
     */
    val resultReady: Boolean,
    /**
     * The last analysed walked run's timing.
     */
    val timing: MeasureTiming?,
    /**
     * Gaps and repeats seen in the capture's frame indices (any one aborts
     * the session, S5).
     */
    val frameFaults: Long,
    /**
     * Who started the session: 0 the app itself, else an agent's actor
     * (`actor::actor_label` names it), so a screen can say "requested by
     * AI".
     */
    val actor: Long,
)

/**
 * What to detect (`detect_start`). Every field may be left out.
 */
data class DetectSetup(
    /**
     * The outputs, 0-based; empty for every output of the device.
     */
    val outputs: List<Int>,
    /**
     * Where the microphone is: the listening position (default), near
     * field, or a headphone coupler (the headphones' levels).
     */
    val placement: MeasurePlacement,
    /**
     * The coupler, for headphones.
     */
    val coupler: MeasureCoupler?,
    /**
     * The floor for every output, Hz: 0 for 1 kHz; may only raise it (1000
     * to 8000). The limits profile's `highpass_min_hz` raises an output's
     * own further.
     */
    val floorHz: Float,
    /**
     * The microphone's `mic` document's text ("" uncalibrated).
     */
    val micDocument: String,
    /**
     * The SPL cap with a calibrated microphone (as `MeasureSetup`).
     */
    val splCapDb: Float?,
    /**
     * The capture's rate, Hz (0: 48000).
     */
    val captureRateHz: Long,
    /**
     * The top-fall check only (stages A and B, never below the floor) of
     * the listed outputs' stated roles: no class, no layout row; each
     * output's [`RoleCheck`] goes to the stated layout. Refused when the
     * layout is not stated or a listed output is not a stated row.
     */
    val check: Boolean,
)

/**
 * The detection's state.
 */
data class DetectState(
    /**
     * Where it stands.
     */
    val stage: DetectStage,
    /**
     * Tick it (`detect_tick`): a session runs or is next.
     */
    val running: Boolean,
    /**
     * The output probed now (or last).
     */
    val output: Int?,
    /**
     * Outputs finished so far.
     */
    val outputsDone: Int,
    /**
     * Outputs to probe (those off or muted are not).
     */
    val outputsTotal: Int,
    /**
     * The output's floor, Hz.
     */
    val floorHz: Float,
    /**
     * The segment's start (or the band's bottom), Hz.
     */
    val segmentHz: Float,
    /**
     * The level it plays at (the ramp's ceiling while ramping), peak dBFS.
     */
    val levelDbfs: Float,
    /**
     * The session (push capture while it wants it).
     */
    val session: MeasureState,
    /**
     * The detection so far: each output's class and evidence, the summary.
     */
    val detection: Detection?,
    /**
     * Why it stopped, or what the last session asked.
     */
    val issue: MeasureIssue?,
    /**
     * Who started it: 0 the app, else an agent's actor.
     */
    val actor: Long,
    /**
     * It is a top-fall check of stated roles ([`DetectSetup::check`]).
     */
    val check: Boolean,
    /**
     * The check's verdicts so far, by output.
     */
    val checks: List<RoleCheck>,
)

/**
 * How to give a measurement's curves (`measure_doc_curves`).
 */
data class MeasureDocCurvesOptions(
    /**
     * The smoothing, 1/N octave (1 to 48); 0 for none.
     */
    val smoothing: Int,
    /**
     * Give the target too, levelled to each output's curve.
     */
    val target: Boolean,
    /**
     * A `target` document's text; "" for the placement's default target.
     */
    val targetDocument: String,
)

/**
 * One output's curves.
 */
data class MeasureDocCurve(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * Its way.
     */
    val role: MeasureRole,
    /**
     * The speaker it belongs to ("" when the layout named none).
     */
    val speaker: String,
    /**
     * The measured response, smoothed (untrusted points flagged).
     */
    val measured: MeasureLiveCurve,
    /**
     * The target levelled to the measured response, when asked for.
     */
    val target: MeasureLiveCurve?,
    /**
     * Per point, the spread across positions or reseats, dB; empty when
     * the document has none.
     */
    val spreadDb: List<Double>,
)

/**
 * A measurement document's curves (`measure_doc_curves`).
 */
data class MeasureDocCurves(
    /**
     * The smoothing applied, 1/N octave; 0 none.
     */
    val smoothing: Int,
    /**
     * The run's timing was reliable.
     */
    val timingReliable: Boolean,
    /**
     * One per measured output, in the document's order.
     */
    val outputs: List<MeasureDocCurve>,
)

/**
 * What the live view measures and how (`measure_live_start`). Every number
 * 0 (or absent) is the default.
 */
data class MeasureLiveSetup(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * Sweeps or pink noise with the RTA.
     */
    val mode: MeasureLiveMode,
    /**
     * Its way (the tweeter rule, S6, needs `mid` or `high` for those).
     */
    val role: MeasureRole,
    /**
     * Where the microphone is: the listening position, near field, or a
     * headphone coupler (several positions are not live).
     */
    val placement: MeasurePlacement,
    /**
     * The coupler, for headphones.
     */
    val coupler: MeasureCoupler?,
    /**
     * The microphone's `mic` document's text; "" for an uncalibrated one.
     */
    val micDocument: String,
    /**
     * A `target` document's text; "" for the placement's default target.
     */
    val targetDocument: String,
    /**
     * The graph's smoothing, 1/N octave (1 to 48); 0 for none.
     */
    val smoothing: Int,
    /**
     * One sweep, ms (1000 to 15000; 0: 2700).
     */
    val sweepMs: Long,
    /**
     * The gap after a sweep, ms (300 to 2000; 0: the placement's).
     */
    val gapMs: Long,
    /**
     * Pink noise per run, ms (1000 to 60000; 0: 30000, then re-armed).
     */
    val pinkMs: Long,
    /**
     * The generator's ceiling, peak dBFS (as a measurement's).
     */
    val ceilingDb: Float?,
    /**
     * The SPL cap with a calibrated microphone, dB SPL (as a measurement's).
     */
    val splCapDb: Float?,
    /**
     * The capture's rate, Hz (0: 48000).
     */
    val captureRateHz: Long,
    /**
     * The RTA's averaging.
     */
    val averaging: MeasureRtaAveraging,
    /**
     * The RTA's bands per octave (1 to 48; 0: 3).
     */
    val bandsPerOctave: Int,
    /**
     * Take `role` from the device's stored speaker layout (MPLAN 2.2);
     * refused (`measure.layout_unconfirmed`) while it is not confirmed.
     */
    val rolesFromLayout: Boolean,
)

/**
 * A curve as the live graph draws it (10 Hz to 22 kHz, 1/48 octave).
 */
data class MeasureLiveCurve(
    /**
     * Frequencies, Hz, ascending.
     */
    val freqsHz: List<Double>,
    /**
     * Magnitude, dB (dB SPL when `spl`).
     */
    val magDb: List<Double>,
    /**
     * Per point, trusted (untrusted points are drawn faint).
     */
    val valid: List<Boolean>,
    /**
     * The magnitudes are dB SPL (a calibrated microphone).
     */
    val spl: Boolean,
)

/**
 * One PEQ band of the live output, as a proposal writes it.
 */
data class MeasureLiveBand(
    /**
     * The PEQ band, 0-based.
     */
    val band: Int,
    /**
     * The firmware's filter type (0 flat, 1 peak, 2 low shelf, 3 high
     * shelf, ...).
     */
    val filterType: Int,
    /**
     * Switched off.
     */
    val bypass: Boolean,
    /**
     * Centre or corner, Hz.
     */
    val freq: Float,
    /**
     * Q.
     */
    val q: Float,
    /**
     * Gain, dB.
     */
    val gain: Float,
    /**
     * The Linkwitz Transform's target Q; unused otherwise.
     */
    val qp: Float,
)

/**
 * One band a proposal changes.
 */
data class MeasureLiveChange(
    /**
     * The PEQ band, 0-based.
     */
    val band: Int,
    /**
     * What it is now.
     */
    val before: MeasureLiveBand,
    /**
     * What the proposal writes.
     */
    val after: MeasureLiveBand,
    /**
     * The change in words ("PEQ band 4: flat → peak -5.8 dB at 1.02 kHz,
     * Q 4.1").
     */
    val words: String,
)

/**
 * A direct adjustment, previewed: nothing is written until
 * `measure_live_apply` with its id.
 */
data class MeasureLiveProposal(
    /**
     * Its id (`measure_live_apply`).
     */
    val id: Long,
    /**
     * What made it.
     */
    val adjust: MeasureLiveAdjust,
    /**
     * The output.
     */
    val output: Int,
    /**
     * The undo step's label.
     */
    val label: String,
    /**
     * The bands it writes (empty: nothing to change, see `issue`).
     */
    val changes: List<MeasureLiveChange>,
    /**
     * The output's gain now, dB.
     */
    val gainBeforeDb: Float,
    /**
     * The output's gain it writes, dB (a headroom cut; equal: unchanged).
     */
    val gainAfterDb: Float,
    /**
     * The RMS error to the target in the span before, dB (a fit's).
     */
    val rmsBeforeDb: Double,
    /**
     * The same, predicted after, dB.
     */
    val rmsAfterDb: Double,
    /**
     * What was done and why, in words.
     */
    val notes: List<String>,
    /**
     * Why nothing is proposed, when nothing is.
     */
    val issue: MeasureIssue?,
    /**
     * The curve the change is predicted to give.
     */
    val predicted: MeasureLiveCurve?,
)

/**
 * The microphone RTA of the live view.
 */
data class MeasureLiveRta(
    /**
     * The averaged spectrum in fractional-octave bands (dBFS, or dB SPL).
     */
    val current: MeasureLiveCurve?,
    /**
     * The held copy.
     */
    val held: MeasureLiveCurve?,
    /**
     * The current spectrum minus the held one, dB.
     */
    val compare: MeasureLiveCurve?,
    /**
     * FFT frames averaged so far.
     */
    val frames: Long,
    /**
     * The averaging preset.
     */
    val averaging: MeasureRtaAveraging,
)

/**
 * What the live view shows now (`measure_live_frame`).
 */
data class MeasureLiveFrame(
    /**
     * The live view runs.
     */
    val active: Boolean,
    /**
     * What it plays.
     */
    val mode: MeasureLiveMode,
    /**
     * The output.
     */
    val output: Int,
    /**
     * Counts the measured curves (one per sweep; the RTA's per update).
     */
    val seq: Long,
    /**
     * The measured curve, if one.
     */
    val measured: MeasureLiveCurve?,
    /**
     * The target, levelled to the measured curve.
     */
    val target: MeasureLiveCurve?,
    /**
     * The predicted curve: of the pending change, or of a change already
     * written that no sweep has measured yet.
     */
    val predicted: MeasureLiveCurve?,
    /**
     * The microphone RTA (pink mode).
     */
    val rta: MeasureLiveRta?,
    /**
     * The change previewed, if one.
     */
    val pending: MeasureLiveProposal?,
    /**
     * Why the live view stopped, if it did.
     */
    val issue: MeasureIssue?,
    /**
     * The current run's state.
     */
    val session: MeasureState,
)

/**
 * Where the live view stands (`measure_live_tick` and the other calls).
 */
data class MeasureLiveState(
    /**
     * The live view runs.
     */
    val active: Boolean,
    /**
     * What it plays.
     */
    val mode: MeasureLiveMode,
    /**
     * The output.
     */
    val output: Int,
    /**
     * Counts the measured curves.
     */
    val seq: Long,
    /**
     * Runs started (sweeps, or pink runs).
     */
    val runs: Long,
    /**
     * The level the next run starts its ramp at, peak dBFS.
     */
    val levelDb: Float?,
    /**
     * The pending proposal's id, if one.
     */
    val pending: Long?,
    /**
     * Why the live view stopped, if it did.
     */
    val issue: MeasureIssue?,
    /**
     * The current run's state.
     */
    val session: MeasureState,
)

/**
 * What the passive RTA analyses (`measure_rta_passive_start`). Every number
 * 0 (or absent) is the default.
 */
data class MeasureRtaPassiveSetup(
    /**
     * The microphone's `mic` document's text; "" for an uncalibrated one
     * (dBFS). A calibrated one gives dB SPL when its scale is known.
     */
    val micDocument: String,
    /**
     * The capture's rate, Hz (8000 to 192000; 0: 48000).
     */
    val captureRateHz: Long,
    /**
     * The averaging preset.
     */
    val averaging: MeasureRtaAveraging,
    /**
     * Bands per octave (1 to 48; 0: 3).
     */
    val bandsPerOctave: Int,
)

/**
 * Where the passive RTA stands.
 */
data class MeasureRtaPassiveState(
    /**
     * It runs.
     */
    val active: Boolean,
    /**
     * The capture's rate, Hz.
     */
    val captureRateHz: Long,
    /**
     * Bands per octave.
     */
    val bandsPerOctave: Int,
    /**
     * The averaging preset.
     */
    val averaging: MeasureRtaAveraging,
    /**
     * FFT frames averaged since the start (or the last change of averaging).
     */
    val frames: Long,
    /**
     * Non-finite samples seen (analysed as silence).
     */
    val nonfiniteSamples: Long,
    /**
     * A spectrum is held for comparison.
     */
    val held: Boolean,
    /**
     * The spectrum is dB SPL (a calibrated microphone), else dBFS.
     */
    val spl: Boolean,
)

/**
 * What the passive RTA shows (`measure_rta_passive_frame`).
 */
data class MeasureRtaPassiveFrame(
    /**
     * Its state.
     */
    val state: MeasureRtaPassiveState,
    /**
     * The spectrum, the held copy and their difference, as the live view's
     * RTA gives them; `None` when it does not run.
     */
    val rta: MeasureLiveRta?,
)

/**
 * What to search (`measure_rolloff_start`). Every number 0 (or absent) is
 * the default.
 */
data class MeasureRolloffSetup(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * Its way as the caller has it; the effective role (a high-pass at
     * 1 kHz or above makes it a tweeter) is what counts. Ignored with
     * `roles_from_layout`.
     */
    val role: MeasureRole,
    /**
     * Take the role from the device's confirmed speaker layout (agents
     * always do; refused with `measure.layout_unconfirmed` without one).
     */
    val rolesFromLayout: Boolean,
    /**
     * The speaker it belongs to, for the document.
     */
    val speaker: String,
    /**
     * Where the microphone is: near field (close to the driver, which
     * judges a driver best) or (-- WP FEAT2 --) on a headphone coupler, with
     * the headphones' level caps; any other placement is taken as the
     * listening position.
     */
    val placement: MeasurePlacement,
    /**
     * The microphone's `mic` document's text ("" uncalibrated).
     */
    val micDocument: String,
    /**
     * The first segment's start, Hz (0: 8 kHz; at most 10 kHz; never below
     * the output's floor).
     */
    val startHz: Float,
    /**
     * One sweep, ms (1000 to 15000; 0: 2700).
     */
    val sweepMs: Long,
    /**
     * The generator's ceiling, peak dBFS (as `MeasureSetup::ceiling_db`).
     */
    val ceilingDb: Float?,
    /**
     * The SPL cap with a calibrated microphone (as `MeasureSetup`).
     */
    val splCapDb: Float?,
    /**
     * The capture's rate, Hz (0: 48000).
     */
    val captureRateHz: Long,
    /**
     * The documents' name ("" names them by the date).
     */
    val name: String,
    /**
     * Play at the start level only (as `MeasureSetup::start_level_only`).
     */
    val startLevelOnly: Boolean,
    /**
     * The coupler, for headphones (as `MeasureSetup::coupler`).
     */
    val coupler: MeasureCoupler?,
)

/**
 * The search's result.
 */
data class MeasureRolloffResult(
    /**
     * The output.
     */
    val output: Int,
    /**
     * Its effective role.
     */
    val role: MeasureRole,
    /**
     * Why it ended.
     */
    val end: MeasureRolloffEnd,
    /**
     * The threshold it stopped at, dB below the loudest point.
     */
    val stopDb: Float,
    /**
     * The loudest point of the smoothed response, dB (re a 0 dBFS
     * stimulus, or dB SPL with `spl`).
     */
    val referenceDb: Double,
    /**
     * Where that loudest point is, Hz.
     */
    val referenceHz: Double,
    /**
     * Where the response falls `stop_db` below the loudest point, Hz;
     * `None` when it never did above the floor.
     */
    val rolloffHz: Double?,
    /**
     * The lowest frequency any stimulus played, Hz.
     */
    val lowestHz: Double,
    /**
     * The smoothed level at the lowest judged frequency, dB re the loudest
     * point (at most 0).
     */
    val lowEndDb: Double,
    /**
     * The note for the user: `measure.rolloff.midrange` for a tweeter still
     * good at its floor.
     */
    val note: MeasureIssue?,
    /**
     * The last segment's trusted points in its judged band, Hz.
     */
    val freqsHz: List<Double>,
    /**
     * The smoothed level at each of `freqs_hz`, dB (as `reference_db`).
     */
    val magDb: List<Double>,
    /**
     * The levels are dB SPL (a calibrated microphone).
     */
    val spl: Boolean,
    /**
     * The last segment's `measurement` document (file it with
     * `measure_doc_put`).
     */
    val document: String,
)

/**
 * The search's state.
 */
data class MeasureRolloffState(
    /**
     * Where it stands.
     */
    val stage: MeasureRolloffStage,
    /**
     * Tick it (`measure_rolloff_tick`): a segment runs or is next.
     */
    val running: Boolean,
    /**
     * The output searched.
     */
    val output: Int?,
    /**
     * Its effective role.
     */
    val role: MeasureRole,
    /**
     * The lowest any segment may start, Hz (1000 on a tweeter).
     */
    val floorHz: Float,
    /**
     * The segment now (or last) measured, 1-based.
     */
    val segment: Int,
    /**
     * The most segments there can be (the floor reached).
     */
    val segments: Int,
    /**
     * That segment's start, Hz.
     */
    val segmentStartHz: Float,
    /**
     * The segment's session (push capture while it wants it).
     */
    val session: MeasureState,
    /**
     * The result, once done.
     */
    val result: MeasureRolloffResult?,
    /**
     * Why it stopped, or what the last segment asked.
     */
    val issue: MeasureIssue?,
    /**
     * Who started it: 0 the app, else an agent's actor.
     */
    val actor: Long,
)

/**
 * One unit of a system measurement and the outputs measured on it.
 */
data class MeasureSystemUnit(
    /**
     * Its USB serial (as the hub knows it).
     */
    val serial: String,
    /**
     * Its outputs to measure, 1 to 16, each once (`group` is ignored: the
     * group is the whole setup).
     */
    val outputs: List<MeasureOutput>,
)

/**
 * What to measure across units and how (PLAN-AT 1.4). Every number 0 (or
 * absent) is the plan's default.
 */
data class MeasureSystemSetup(
    /**
     * The group's units, 2 to 16, in the order the hub opens them.
     */
    val units: List<MeasureSystemUnit>,
    /**
     * Passes, 2 to 8; 0: 5 where the run fits one capture, else 3.
     */
    val passes: Int,
    /**
     * The anchor output's unit for runs chained through it; "": the first
     * unit.
     */
    val anchorSerial: String,
    /**
     * The anchor output; `None`: the anchor unit's first output.
     */
    val anchorOutput: Int?,
    /**
     * The microphone's `mic` document's text; "" for an uncalibrated one.
     */
    val micDocument: String,
    /**
     * One sweep, ms (1000 to 15000; 0: 5500).
     */
    val sweepMs: Long,
    /**
     * The gap after each cycle, ms (300 to 2000; 0: 1000).
     */
    val gapMs: Long,
    /**
     * The generator's ceiling, peak dBFS (as P5's).
     */
    val ceilingDb: Float?,
    /**
     * The SPL cap with a calibrated microphone, dB SPL (as P5's).
     */
    val splCapDb: Float?,
    /**
     * The capture's rate, Hz (0: 48000).
     */
    val captureRateHz: Long,
    /**
     * The lead of every START, ms; 0 or less than the units' arm lead plus
     * 100 ms: that (S-AT3).
     */
    val leadMs: Long,
    /**
     * The hub's lease, ms (0: the hub's default, 2000; clamped 500..5000).
     */
    val leaseMs: Long,
    /**
     * The documents' name ("" names them by the date).
     */
    val name: String,
)

/**
 * One unit judged by its own core (P5's preflight on that unit's mirror),
 * for the core on the hub session.
 */
data class MeasureSystemUnitCheck(
    /**
     * The unit's serial.
     */
    val serial: String,
    /**
     * P5's preflight of its outputs.
     */
    val preflight: MeasurePreflight,
    /**
     * What the session needs of the unit (its platform, rate, inputs,
     * limiters, the measured chains), as JSON. Opaque to clients.
     */
    val context: String,
)

/**
 * An issue of a system measurement, naming its unit.
 */
data class MeasureSystemIssue(
    /**
     * The unit's serial; "" when it concerns no one unit.
     */
    val serial: String,
    /**
     * The notice key (`measure.*`, `measure.system.*`).
     */
    val key: String,
    /**
     * The output it concerns, if one.
     */
    val output: Int?,
    /**
     * What happened, in words (the unit named).
     */
    val message: String,
)

/**
 * What stands between a setup and a system measurement.
 */
data class MeasureSystemPreflight(
    /**
     * Nothing blocks.
     */
    val clear: Boolean,
    /**
     * What must change first, each naming its unit.
     */
    val blockers: List<MeasureSystemIssue>,
    /**
     * What to know.
     */
    val warnings: List<MeasureSystemIssue>,
)

/**
 * One output's level after its ramp.
 */
data class MeasureSystemLevel(
    /**
     * The unit.
     */
    val serial: String,
    /**
     * The output.
     */
    val output: Int,
    /**
     * Its level, peak dBFS.
     */
    val levelDb: Float,
)

/**
 * A system session's state (no I/O to read it).
 */
data class MeasureSystemState(
    /**
     * The phase.
     */
    val phase: MeasureSystemPhase,
    /**
     * What the runs are for.
     */
    val purpose: MeasureSystemPurpose,
    /**
     * Holds the hub's session or a stage in progress.
     */
    val active: Boolean,
    /**
     * Push the microphone's capture now.
     */
    val wantsCapture: Boolean,
    /**
     * The capture's rate, Hz.
     */
    val captureRateHz: Long,
    /**
     * The unit playing (a ramp step), or "".
     */
    val serial: String,
    /**
     * The output playing (a ramp step).
     */
    val output: Int?,
    /**
     * Its level, peak dBFS.
     */
    val levelDb: Float?,
    /**
     * Every level the ramps found so far.
     */
    val rampLevels: List<MeasureSystemLevel>,
    /**
     * The timed run in progress, 1-based (0 before the first).
     */
    val run: Int,
    /**
     * Timed runs in all.
     */
    val runs: Int,
    /**
     * Capture frames pushed.
     */
    val frames: Long,
    /**
     * Progress of the stage, 0 to 1.
     */
    val progress: Float,
    /**
     * Why it stopped or what it asks.
     */
    val issue: MeasureSystemIssue?,
    /**
     * A result is ready (`measure_system_result`).
     */
    val resultReady: Boolean,
    /**
     * G5: the timing of every run was reliable.
     */
    val timingReliable: Boolean?,
    /**
     * What the session waits for, in words ("waiting for the units' clocks
     * to settle"), or "".
     */
    val words: String,
)

/**
 * A measured output's arrival, as the proposal would write it.
 */
data class MeasureSystemArrival(
    /**
     * The unit.
     */
    val serial: String,
    /**
     * The output.
     */
    val output: Int,
    /**
     * Its acoustic arrival relative to the group's latest output, us (0 for
     * that one, negative for an earlier one): WP ATHUBM's
     * `measuredArrivalUs`.
     */
    val arrivalUs: Double,
    /**
     * The arrival as measured on the timeline, before the engine's terms
     * were taken out, relative to the same reference, us.
     */
    val measuredUs: Double,
    /**
     * The uncertainty of the arrival against the latest output, us (one
     * standard error; `None` without two clear passes).
     */
    val uncertaintyUs: Double?,
    /**
     * May be proposed: the gate passed and the delay to the latest output
     * is offered (within 10 us).
     */
    val offered: Boolean,
    /**
     * Why not (empty when offered).
     */
    val reason: String,
)

/**
 * A delay between two outputs on different units of one run.
 */
data class MeasureSystemDelay(
    /**
     * The earlier output's unit.
     */
    val fromSerial: String,
    /**
     * Its output.
     */
    val fromOutput: Int,
    /**
     * The other output's unit.
     */
    val toSerial: String,
    /**
     * Its output.
     */
    val toOutput: Int,
    /**
     * `to`'s arrival minus `from`'s, us.
     */
    val delayUs: Double,
    /**
     * Its uncertainty, us.
     */
    val uncertaintyUs: Double?,
    /**
     * The analyser offers it.
     */
    val offered: Boolean,
    /**
     * Why not ("timing unreliable: ..." with the wander).
     */
    val reason: String,
)

/**
 * An inter-unit transition and its summed check (RC5f, R8d).
 */
data class MeasureSystemTransition(
    /**
     * One output's unit.
     */
    val aSerial: String,
    /**
     * Its output.
     */
    val aOutput: Int,
    /**
     * The other output's unit.
     */
    val bSerial: String,
    /**
     * Its output.
     */
    val bOutput: Int,
    /**
     * The check band, Hz.
     */
    val bandLoHz: Double,
    /**
     * The check band's top, Hz.
     */
    val bandHiHz: Double,
    /**
     * The summed run was measured and judged.
     */
    val checked: Boolean,
    /**
     * Within 1.5 dB RMS of the prediction.
     */
    val passed: Boolean,
    /**
     * The RMS difference, dB.
     */
    val rmsDb: Double?,
    /**
     * What happened, in words.
     */
    val message: String,
)

/**
 * One unit's `measurement` document.
 */
data class MeasureSystemDocument(
    /**
     * The unit.
     */
    val serial: String,
    /**
     * The document's text (schema 1 with a `system` block). File it with
     * `measure_doc_put` (or the hub's).
     */
    val document: String,
)

/**
 * A finished system measurement.
 */
data class MeasureSystemResult(
    /**
     * One document per unit.
     */
    val documents: List<MeasureSystemDocument>,
    /**
     * Every measured output's arrival.
     */
    val arrivals: List<MeasureSystemArrival>,
    /**
     * Every cross-unit delay of every run.
     */
    val delays: List<MeasureSystemDelay>,
    /**
     * The inter-unit transitions.
     */
    val transitions: List<MeasureSystemTransition>,
    /**
     * G5 for every run.
     */
    val timingReliable: Boolean,
    /**
     * Why not reliable, what was not offered, a refused chain.
     */
    val reasons: List<String>,
    /**
     * The generator runs (`EXT_SIGGEN_TIMELINE.run_id`) the arrivals came
     * from.
     */
    val runIds: List<Long>,
    /**
     * Timed runs chained through the anchor (1: none).
     */
    val runs: Int,
    /**
     * Which plan each run used: "overlapped starts, 50 ms apart" (the
     * default where it is safe) or "interleaved passes" with why
     * overlapped starts were not used; "run 1: ...; run 2: ..." for
     * chained runs.
     */
    val plan: String,
)

/**
 * The alignment a system measurement proposes (OD-ATl): measured arrivals
 * into the hub's model, applied by `system.align`.
 */
data class MeasureSystemProposal(
    /**
     * Its id (the apply names it).
     */
    val id: Long,
    /**
     * The arrivals to write: offered ones only.
     */
    val arrivals: List<MeasureSystemArrival>,
    /**
     * Arrivals not offered, with why.
     */
    val withheld: List<MeasureSystemArrival>,
    /**
     * The transitions and their summed checks.
     */
    val transitions: List<MeasureSystemTransition>,
    /**
     * A summed check is still to run before anything may be applied.
     */
    val sumCheckNeeded: Boolean,
    /**
     * Every cross-unit delay was withdrawn (a summed check failed).
     */
    val withdrawn: Boolean,
    /**
     * Something can be applied (after the summed check).
     */
    val offered: Boolean,
    /**
     * This session's role may apply it (Admin).
     */
    val mayApply: Boolean,
    /**
     * What stands in the way, if anything.
     */
    val notice: MeasureSystemIssue?,
    /**
     * The hub's guard the apply begins, s: the hub reverts the apply by
     * itself unless it is kept within this long (and when this console's
     * connection is lost). 0: the hub has no guard for a system apply.
     */
    val guardS: Long,
    /**
     * The guard in words: how long, or that nothing reverts by itself.
     */
    val guardNote: String,
)

/**
 * One unit's output delays as filed before an apply.
 */
data class MeasureSystemSnapshot(
    /**
     * The unit.
     */
    val serial: String,
    /**
     * `(output, out.delay ms)` read before the apply.
     */
    val outDelaysMs: List<MeasureSystemOutDelay>,
)

/**
 * One output's delay.
 */
data class MeasureSystemOutDelay(
    /**
     * The output.
     */
    val output: Int,
    /**
     * Its delay, ms.
     */
    val delayMs: Float,
)

/**
 * What an apply, a verify, a Keep or a Revert did.
 */
data class MeasureSystemApplied(
    /**
     * Where it stands.
     */
    val stage: MeasureSystemApplyStage,
    /**
     * The hub model's revision filed before the apply.
     */
    val revisionBefore: Long,
    /**
     * Its revision after the apply (or the revert).
     */
    val revisionAfter: Long,
    /**
     * Every unit's output delays filed before the apply.
     */
    val snapshots: List<MeasureSystemSnapshot>,
    /**
     * `system.align`'s writes that were `ok`.
     */
    val writesOk: Long,
    /**
     * Writes that failed, in words.
     */
    val writeFailures: List<String>,
    /**
     * The verify's summed runs agreed with the new delays (`None` before).
     */
    val verified: Boolean?,
    /**
     * What to know, in words.
     */
    val message: String,
    /**
     * The hub's guard of this apply, s (0: none, nothing reverts by
     * itself): the hub sets the filed model back and aligns at the
     * deadline unless Keep confirms it, and when the connection is lost.
     */
    val guardS: Long,
    /**
     * The notice key when the revert was not fully successful (stage
     * `RevertIncomplete`): `revert.incomplete`, `revert.failed`,
     * `revert.not_written` or `revert.unknown`; "" otherwise. `message`
     * names what was not put back.
     */
    val revertNotice: String,
)

/**
 * One output of a layout (PLAN-P5 section 1.4 step 1).
 */
data class MeasureLayoutOutput(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * Its way.
     */
    val role: MeasureRole,
    /**
     * The speaker it belongs to (`L`, `R`, `Sub`, ...): the ways of one
     * speaker are tuned together.
     */
    val speaker: String,
    /**
     * Its alignment group: one walked run measures a group.
     */
    val group: Int,
    /**
     * The output's user name, if it has one.
     */
    val name: String,
    /**
     * The input that feeds it most (its programme source), if one.
     */
    val feedInput: Int?,
    /**
     * The net crosspoint gain of that source, dB.
     */
    val feedGainDb: Float,
    /**
     * The net polarity of its feeding crosspoints is inverted.
     */
    val feedInverted: Boolean,
)

/**
 * The speakers and ways the tune works on (`measure_layout_proposal`;
 * confirmed or edited by the user).
 */
data class MeasureLayout(
    /**
     * The outputs, each once.
     */
    val outputs: List<MeasureLayoutOutput>,
    /**
     * The layout recognised (`3way`, `2way`, `headphones`, `full range`),
     * "" when none.
     */
    val template: String,
    /**
     * Remarks in words.
     */
    val notes: List<String>,
)

/**
 * What the tune may change (`measure_tune_propose`). Every number 0 is the
 * default.
 */
data class MeasureTuneOptions(
    /**
     * A `target` document's text; "" for the placement's default target.
     */
    val targetDocument: String,
    /**
     * The measurement's microphone's `mic` document; "" looks it up by the
     * id the measurement names (needed for the summed and verify runs).
     */
    val micDocument: String,
    /**
     * "Keep the crossover, align only": no corner or level change.
     */
    val keepCrossover: Boolean,
    /**
     * Keep the current delays (polarity is still judged).
     */
    val keepDelays: Boolean,
    /**
     * Keep every output gain of the crossover.
     */
    val keepLevels: Boolean,
    /**
     * No EQ fit.
     */
    val keepEq: Boolean,
    /**
     * The corner search's window each side, octaves (0: 0.5; at most 2).
     */
    val windowOctaves: Double,
    /**
     * The fit's range, Hz (0: 20 Hz to 300 Hz for speakers, 20 Hz to 10 kHz
     * for headphones).
     */
    val fitMinHz: Double,
    /**
     * See `fit_min_hz`.
     */
    val fitMaxHz: Double,
    /**
     * Take the layout's roles, speakers and groups from the device's stored
     * speaker layout (MPLAN 2.2, `roles: "layout"`); a layout with no
     * outputs then means every output of it. Refused
     * (`measure.layout_unconfirmed`) while the user has not confirmed it.
     */
    val rolesFromLayout: Boolean,
)

/**
 * One parameter of a write: what `write_param` gets.
 */
data class MeasureTuneParam(
    /**
     * The registry path (`out.delay`, `eq.freq`, `mix`, ...).
     */
    val path: String,
    /**
     * Its indices.
     */
    val indices: List<Int>,
    /**
     * The value written.
     */
    val value: ParamValue,
)

/**
 * One change of a proposal, in words, with the parameters it writes.
 */
data class MeasureTuneWrite(
    /**
     * The output it changes.
     */
    val output: Int,
    /**
     * What it changes.
     */
    val kind: MeasureTuneKind,
    /**
     * A delay, polarity, crossover or level write: offered only from a
     * timing-reliable run, applied only after the summed check passed.
     */
    val timing: Boolean,
    /**
     * The change in words ("Out 3 (L high): delay 0.0000 → 0.2100 ms").
     */
    val words: String,
    /**
     * What is written, in order.
     */
    val params: List<MeasureTuneParam>,
)

/**
 * A speaker's curves: before, predicted, the target levelled to before.
 */
data class MeasureTuneCurves(
    /**
     * The speaker.
     */
    val speaker: String,
    /**
     * The ways' sum with phase (a timing-reliable run); else their power sum.
     */
    val coherent: Boolean,
    /**
     * The speaker as it is now (programme audio).
     */
    val before: MeasureLiveCurve,
    /**
     * The speaker with the proposal.
     */
    val predicted: MeasureLiveCurve,
    /**
     * The target, levelled to `before`.
     */
    val target: MeasureLiveCurve,
)

/**
 * One transition of a proposal.
 */
data class MeasureTuneTransition(
    /**
     * The speaker.
     */
    val speaker: String,
    /**
     * The lower way's output.
     */
    val lowOutput: Int,
    /**
     * The upper way's output.
     */
    val highOutput: Int,
    /**
     * The corner now, Hz.
     */
    val cornerBeforeHz: Double,
    /**
     * The proposed corner, Hz.
     */
    val cornerHz: Double,
    /**
     * The upper way's delay minus the lower way's, as proposed, ms.
     */
    val relativeDelayMs: Double,
    /**
     * The upper way's polarity is flipped relative to the lower way's.
     */
    val flipped: Boolean,
    /**
     * The summed check's RMS difference, dB, once run.
     */
    val sumCheckRmsDb: Double?,
    /**
     * The verify's summed RMS difference, dB, once run.
     */
    val verifyRmsDb: Double?,
)

/**
 * A proposal: nothing is written until it is applied.
 */
data class MeasureTuneProposal(
    /**
     * Its id, for `measure_tune_apply` (a new id after a summed check).
     */
    val id: Long,
    /**
     * The device it is for.
     */
    val serial: String,
    /**
     * The measurement's id ("" for one given as text).
     */
    val measurementId: String,
    /**
     * The measurement's name.
     */
    val measurementName: String,
    /**
     * Every write, in the order it is applied.
     */
    val writes: List<MeasureTuneWrite>,
    /**
     * Each speaker's curves.
     */
    val curves: List<MeasureTuneCurves>,
    /**
     * Each transition.
     */
    val transitions: List<MeasureTuneTransition>,
    /**
     * The limits it was held to, in words.
     */
    val held: List<String>,
    /**
     * What is not offered, and why.
     */
    val withdrawn: List<MeasureIssue>,
    /**
     * What the user should know (an old measurement, another placement).
     */
    val warnings: List<MeasureIssue>,
    /**
     * Remarks of the maths, in words.
     */
    val notes: List<String>,
    /**
     * The measurement passed the timing quality gate.
     */
    val timingReliable: Boolean,
    /**
     * The summed check.
     */
    val sumCheck: MeasureTuneCheck,
)

/**
 * One output's verify.
 */
data class MeasureTuneVerifyOutput(
    /**
     * The output.
     */
    val output: Int,
    /**
     * RMS difference of the measured response from the predicted one, dB,
     * over the points both trust within 30 dB of the loudest; `None` when
     * too few.
     */
    val rmsDb: Double?,
)

/**
 * One speaker's verified sum.
 */
data class MeasureTuneVerifySum(
    /**
     * The speaker.
     */
    val speaker: String,
    /**
     * RMS difference of the verified programme sum (the verify run's ways
     * summed with their phase) from the predicted one, 200 Hz to 10 kHz,
     * dB; `None` without timing.
     */
    val rmsDb: Double?,
)

/**
 * What the verify runs found.
 */
data class MeasureTuneVerify(
    /**
     * Each tuned output.
     */
    val outputs: List<MeasureTuneVerifyOutput>,
    /**
     * Each speaker with timing.
     */
    val sums: List<MeasureTuneVerifySum>,
    /**
     * Each transition with its summed run.
     */
    val transitions: List<MeasureTuneTransition>,
    /**
     * The verify's walked run passed the timing quality gate.
     */
    val timingReliable: Boolean,
    /**
     * Every summed run, verified sum and verified output within 1.5 dB RMS
     * of the prediction.
     */
    val passed: Boolean,
    /**
     * Remarks in words.
     */
    val notes: List<String>,
)

/**
 * A tune's state (`measure_tune_tick`, `measure_tune_state`).
 */
data class MeasureTuneState(
    /**
     * Where it stands.
     */
    val stage: MeasureTuneStage,
    /**
     * A summed or verify run is under way: tick and push capture.
     */
    val running: Boolean,
    /**
     * The current proposal's id.
     */
    val proposalId: Long?,
    /**
     * The run under way, 1-based, and the runs of this step.
     */
    val run: Int,
    /**
     * See `run`.
     */
    val runs: Int,
    /**
     * The measurement session under the run.
     */
    val session: MeasureState,
    /**
     * The guard, once applied.
     */
    val guard: GuardedApply,
    /**
     * The verify's result.
     */
    val verify: MeasureTuneVerify?,
    /**
     * Why the last step stopped, if it did.
     */
    val issue: MeasureIssue?,
    /**
     * The "before" snapshot's id ("" when not filed: its text is kept).
     */
    val snapshotBeforeId: String,
    /**
     * The "after" snapshot's id, once kept.
     */
    val snapshotAfterId: String,
)

/**
 * What Keep did (`measure_tune_keep`).
 */
data class MeasureTuneKeep(
    /**
     * The guard's end: `kept`, or the revert's when the timeout came first.
     */
    val guard: GuardedApply,
    /**
     * The "before" snapshot's id and text.
     */
    val snapshotBeforeId: String,
    /**
     * See `snapshot_before_id`.
     */
    val snapshotBefore: String,
    /**
     * The "after" snapshot's id ("" when not filed) and text (with its
     * `tune` block).
     */
    val snapshotAfterId: String,
    /**
     * See `snapshot_after_id`.
     */
    val snapshotAfter: String,
    /**
     * The measurement's id with the tune's row: the same one in this
     * console's store, a new copy's on the hub, "" for a measurement given
     * as text.
     */
    val measurementId: String,
    /**
     * The measurement's text with the tune's row (file it when it was
     * given as text).
     */
    val measurement: String,
    /**
     * What could not be filed, in words.
     */
    val notes: List<String>,
)

/**
 * One measurement, microphone or target document in a list
 * ([`DspiCore::measure_docs`]).
 */
data class MeasureDocInfo(
    /**
     * The store's id, for the other calls ("" for a document not filed).
     */
    val id: String,
    /**
     * The kind: `measurement`, `mic` or `target`.
     */
    val kind: String,
    /**
     * The document's name; any Unicode.
     */
    val name: String,
    /**
     * The user's note; any Unicode.
     */
    val note: String,
    /**
     * The measured device's serial (measurements only, else "").
     */
    val serial: String,
    /**
     * When it was measured (a measurement) or filed (the others), ms since
     * the Unix epoch; 0 when not known.
     */
    val savedMs: Long,
    /**
     * The document's size, bytes.
     */
    val bytes: Long,
)

/**
 * One parameter of a built-in target, with its default.
 */
data class TargetParam(
    /**
     * The parameter's name, as a `target` document's `params` holds it.
     */
    val name: String,
    /**
     * Its default value.
     */
    val value: Double,
)

/**
 * A built-in target ([`target_builtins`]): defined by parameters in our own
 * code, no third-party data (OD-P5p).
 */
data class TargetInfo(
    /**
     * The stable id a `target` document names it by (`flat`, `tilt`,
     * `house`, `coupler-iec60318-4`, `coupler-flat-plate`, `coupler-hats`).
     */
    val id: String,
    /**
     * The display name (it says the curve is ours).
     */
    val name: String,
    /**
     * `speakers` or `headphones`.
     */
    val targetUse: String,
    /**
     * The coupler it is the default for (`iec60318_4`, `flatPlate`,
     * `hats`), "" for a speaker target.
     */
    val coupler: String,
    /**
     * Its parameters with their defaults (none for a fixed curve).
     */
    val params: List<TargetParam>,
)

/**
 * The simulated microphone's state (`measure_sim_info`, `measure_sim_set`).
 */
data class MeasureSimInfo(
    /**
     * This build has it and the open connection is a demo device.
     */
    val available: Boolean,
    /**
     * It is on: it answers the generator, the client pushes nothing.
     */
    val on: Boolean,
    /**
     * What the screens call it ([`SIM_MIC_LABEL`]).
     */
    val label: String,
    /**
     * The world it stands in ([`SIM_WORLD`]).
     */
    val world: String,
    /**
     * The seed its world and noise are drawn from.
     */
    val seed: Long,
    /**
     * Why the last generator configuration could not be rendered (it then
     * hears only the room's noise), if one.
     */
    val issue: String?,
)

/**
 * A mode: Simple, Advanced or Installer.
 */
data class ModeEntry(
    /**
     * `simple`, `advanced` or `installer`.
     */
    val id: String,
    /**
     * The mode's name in the UI.
     */
    val label: String,
    /**
     * The platform classes that open in this mode by default.
     */
    val defaultOn: List<String>,
    /**
     * Behind the installer's PIN when one is set (and only then).
     */
    val needsPinWhenSet: Boolean,
)

/**
 * What the locked-user state shows and allows.
 */
data class ModesLockedUser(
    /**
     * The state's name in the UI (a badge).
     */
    val label: String,
    /**
     * Its screens, in order.
     */
    val screens: List<String>,
    /**
     * What its Settings shows (`about`, `installer_note`).
     */
    val settings: List<String>,
    /**
     * The writes it allows, by registry path (the core enforces them).
     */
    val writes: List<String>,
)

/**
 * A screen and the modes that show it.
 */
data class ModeScreen(
    /**
     * Stable id (`front`, `system`, ...; a lock's cover names these).
     */
    val id: String,
    /**
     * The title in the UI.
     */
    val title: String,
    /**
     * The modes (and `locked_user`) that show it.
     */
    val modes: List<String>,
    /**
     * The modes it is the first screen of.
     */
    val firstIn: List<String>,
    /**
     * `pro` for a Pro-layer screen a client shows once it has built it
     * (else the next screen of the list stands in); "" otherwise.
     */
    val layer: String,
    /**
     * The platform classes it is for; empty: all.
     */
    val platforms: List<String>,
)

/**
 * An operation and the modes that offer it.
 */
data class ModeOperation(
    /**
     * Stable id (`firmware`, `factory_reset`, ...).
     */
    val id: String,
    /**
     * The title in the UI.
     */
    val title: String,
    /**
     * The modes that offer it.
     */
    val modes: List<String>,
    /**
     * The platform classes it is for; empty: all.
     */
    val platforms: List<String>,
    /**
     * Behind its usual confirmation.
     */
    val confirm: Boolean,
)

/**
 * The mode manifest (`assets/modes/modes.json`).
 */
data class ModeManifest(
    /**
     * The format, 1.
     */
    val version: Long,
    /**
     * The platform classes: `phone`, `desktop`, `web`.
     */
    val platforms: List<String>,
    /**
     * The modes, in the order a switch lists them.
     */
    val modes: List<ModeEntry>,
    /**
     * The locked-user state.
     */
    val lockedUser: ModesLockedUser,
    /**
     * The screens, in order.
     */
    val screens: List<ModeScreen>,
    /**
     * The operations that depend on the mode.
     */
    val operations: List<ModeOperation>,
)

/**
 * The mode a client shows, and why ([`DspiCore::mode_resolve`]).
 */
data class ModeChoice(
    /**
     * The mode to show: `simple`, `advanced`, `installer` or `locked_user`.
     */
    val mode: String,
    /**
     * Why: `locked` (the locked-user state), `pinned` (the hub's),
     * `chosen` (the user's) or `default` (the platform class's).
     */
    val reason: String,
    /**
     * The user may switch modes (no lock, no pinned mode).
     */
    val switchable: Boolean,
    /**
     * The mode asked for (chosen or pinned) is the Installer, an installer
     * PIN is set and the console is not unlocked: ask for the PIN
     * (`installer_unlock`); `mode` is the default meanwhile. Never with no
     * PIN set.
     */
    val needsPin: Boolean,
    /**
     * The modes the switch offers with no PIN prompt.
     */
    val openModes: List<String>,
    /**
     * The screens of `mode` for this platform class, in order.
     */
    val screens: List<String>,
    /**
     * The first of them.
     */
    val firstScreen: String,
    /**
     * The operations `mode` offers on this platform class.
     */
    val operations: List<String>,
)

/**
 * One filter type and the name clients show for it.
 */
data class FilterTypeName(
    /**
     * The firmware's type code (`FILTER_*`): 0..13 PEQ, 32..63 crossover.
     */
    val code: Int,
    /**
     * The name, e.g. "High Cut (12dB)".
     */
    val name: String,
)

/**
 * What to tell the user about an error.
 */
data class Notice(
    /**
     * Stable key, for localising: `disconnected`, `dlink.wrong_pin`.
     */
    val key: String,
    /**
     * How to show it.
     */
    val kind: NoticeKind,
    /**
     * A short title.
     */
    val title: String,
    /**
     * Why it happened.
     */
    val reason: String,
    /**
     * What to do.
     */
    val action: String,
    /**
     * The error's own words (may be empty); not localised.
     */
    val detail: String,
)

/**
 * One output's label.
 */
data class OutputLabel(
    /**
     * 0-based output index.
     */
    val output: Int,
    /**
     * What to show: the user's name, else "Out 1 · R · Low".
     */
    val label: String,
    /**
     * The same for a phone row, beside the output's "OUTn" button: the
     * user's name, else "R · Low" (owner decision, review c86 F3).
     */
    val shortLabel: String,
    /**
     * The firmware's name for the slot ("I2S 1 L", "PDM"), for a tooltip or
     * a detail line.
     */
    val slotName: String,
    /**
     * The output has a name the user set; `label` is that name.
     */
    val userNamed: Boolean,
    /**
     * "L", "R", "L+R", an input's name, "Mix", or "None".
     */
    val channel: String,
    /**
     * "Low", "High", "Band" or "Full".
     */
    val band: String,
)

/**
 * One dashboard card: two outputs side by side, or one alone.
 */
data class OutputCard(
    /**
     * 0-based output index of the left (or only) column.
     */
    val left: Int,
    /**
     * The right column's output; none for a card of one output.
     */
    val right: Int?,
    /**
     * "Woofers", "Tweeters" or "Mids" for a pair on one band with default
     * names whose left output plays L and right output R by the routing;
     * empty otherwise.
     */
    val title: String,
    /**
     * The columns' headings: "Woofers L" / "Woofers R" under a title, else
     * the outputs' labels.
     */
    val leftName: String,
    /**
     * The right column's heading; empty for a card of one output.
     */
    val rightName: String,
    /**
     * The left column's heading on a phone: "Woofers L" under a title, else
     * the output's short label ("R · Low").
     */
    val leftShortName: String,
    /**
     * The right column's heading on a phone: "R" under a title, else the
     * output's short label; empty for a card of one output.
     */
    val rightShortName: String,
)

/**
 * The state the labels read, for a client that keeps its own copy.
 */
data class OutputLabelInput(
    /**
     * Live input channels.
     */
    val numInputs: Int,
    /**
     * Live output channels, the PDM sub last.
     */
    val numOutputs: Int,
    /**
     * Per slot: 1 = I2S, else S/PDIF.
     */
    val outputTypes: List<Int>,
    /**
     * Channel names in wire order: inputs, then outputs.
     */
    val channelNames: List<String>,
    /**
     * Crosspoint on, `[input][output]`.
     */
    val matrixRouting: List<List<Boolean>>,
    /**
     * Each output's bands: PEQ and crossover, in any order.
     */
    val outputFilters: List<List<FilterParams>>,
    /**
     * Output enabled, per output.
     */
    val outputEnabled: List<Boolean>,
    /**
     * The K340 crossfeed pair map, 4 bytes; empty or zero elsewhere.
     */
    val crossfeedPairMap: List<Int>,
)

/**
 * A board in BOOTSEL mode with a PICOBOOT interface.
 */
data class BootDevice(
    /**
     * 0 RP2040 (`2E8A:0003`), 1 RP2350 (`2E8A:000F`), as `Uf2Info::platform`.
     */
    val platform: Int,
    /**
     * The boot ROM's USB serial. On an RP2350 it is the chip's unique id,
