/**
 * One output of the layout.
 */
data class SpeakerLayoutOutput(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * What it drives.
     */
    val role: MeasureRole,
    /**
     * The speaker it belongs to (`L`, `R`, `Sub`, or the user's word).
     */
    val speaker: String,
    /**
     * Its alignment group: the outputs of one speaker share one.
     */
    val group: Int,
    /**
     * Where its role comes from: the user, the speaker detection, or a
     * suggestion (a version 1 file's rows are the user's when the layout is
     * confirmed, else suggestions).
     */
    val source: RoleSource,
)

/**
 * Which output drives what, for one device.
 */
data class SpeakerLayout(
    /**
     * The device's serial (set by the core; "" in an exported copy).
     */
    val serial: String,
    /**
     * The outputs, each once, in output order.
     */
    val outputs: List<SpeakerLayoutOutput>,
    /**
     * The user confirmed it (the Getting Started step, Settings ›
     * Speakers). A proposal is never confirmed.
     */
    val confirmedByUser: Boolean,
    /**
     * When it was set, ms since the Unix epoch; 0 for a proposal.
     */
    val updatedMs: Long,
    /**
     * Remarks in words (a proposal's: outputs left out and why).
     */
    val notes: List<String>,
    /**
     * The last speaker detection on this device, if one ran: its evidence
     * per output. With every row `detected` or `user` it makes the layout
     * [`LayoutState::AutoDetected`].
     */
    val detected: Detection?,
    /**
     * The roles an AI agent set from the user's words, if it did: the
     * words, when, and the top-fall checks made since. With a `stated` row
     * and no suggestion it makes the layout [`LayoutState::Stated`].
     */
    val stated: Statement?,
)

/**
 * One output's detection and its evidence.
 */
data class DetectedOutput(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * What it was found to be.
     */
    val class: DetectClass,
    /**
     * How sure.
     */
    val confidence: DetectConfidence,
    /**
     * The role it was given; `None` for `nothing` and `off`.
     */
    val role: MeasureRole?,
    /**
     * Its floor, Hz: nothing below it but the shaped probe.
     */
    val floorHz: Float,
    /**
     * Where it was first heard.
     */
    val heard: DetectHeard,
    /**
     * The level it was heard at in the presence ramp, peak dBFS.
     */
    val levelDbfs: Float?,
    /**
     * The mean level 1.5 to 3 kHz less the mean 10 to 16 kHz, dB.
     */
    val topFallDb: Float?,
    /**
     * How far the response has turned down in the half octave above the
     * floor, dB below its loudest point.
     */
    val lowTurnDb: Float?,
    /**
     * Where the response is 6 dB under its loudest point, Hz; `None` when
     * not reached (or not looked for).
     */
    val fLowHz: Float?,
    /**
     * The lowest frequency any stimulus played on it, Hz.
     */
    val lowestHz: Float?,
    /**
     * The descent's segment it stopped at, Hz.
     */
    val stoppedAtHz: Float?,
    /**
     * A notice key (`detect.nothing`, `detect.off`, `detect.unknown`, ...).
     */
    val note: String?,
    /**
     * When it was probed, ms since the Unix epoch.
     */
    val probedMs: Long,
)

/**
 * A speaker detection's record in the layout.
 */
data class Detection(
    /**
     * When it started, ms since the Unix epoch.
     */
    val atMs: Long,
    /**
     * Who ran it: an agent's label, "" for the app (the user).
     */
    val by: String,
    /**
     * Where the microphone was.
     */
    val placement: measure::MeasurePlacement,
    /**
     * The floor the caller asked for, Hz (each output's own may be higher).
     */
    val floorHz: Float,
    /**
     * The microphone's name ("" uncalibrated).
     */
    val microphone: String,
    /**
     * Each output it was asked about, probed or not.
     */
    val outputs: List<DetectedOutput>,
    /**
     * It was stopped before every output was probed.
     */
    val stopped: Boolean,
    /**
     * The result in words.
     */
    val summary: String,
    /**
     * The device's output count when it ran: another count invalidates it.
     */
    val deviceOutputs: Int,
)

/**
 * One output's top-fall check.
 */
data class RoleCheck(
    /**
     * The output, 0-based.
     */
    val output: Int,
    /**
     * The stated role it checked (a check stands only for that role).
     */
    val role: MeasureRole,
    /**
     * What it found.
     */
    val verdict: RoleCheckVerdict,
    /**
     * The mean level 1.5 to 3 kHz less the mean 10 to 16 kHz, dB.
     */
    val topFallDb: Float?,
    /**
     * The floor it never played below, Hz.
     */
    val floorHz: Float,
    /**
     * When, ms since the Unix epoch.
     */
    val atMs: Long,
    /**
     * Unfinished because the output's own filters (a low-pass) hide its top
     * end: the check judges the driver, not them.
     */
    val filtersHideTop: Boolean,
)

/**
 * The user's words an AI agent set the roles from.
 */
data class Statement(
    /**
     * When, ms since the Unix epoch.
     */
    val atMs: Long,
    /**
     * The agent's label ("AI · Claude Code").
     */
    val by: String,
    /**
     * The user's words, as the agent quoted them.
     */
    val words: String,
    /**
     * Over a confirmed layout: the user's words on what changed ("" else).
     */
    val whatChanged: String,
    /**
     * The device's output count then: another count invalidates it.
     */
    val deviceOutputs: Int,
    /**
     * The top-fall checks made since, by output.
     */
    val checks: List<RoleCheck>,
)

/**
 * A voltage the flow offers on the connected device.
 */
data class VregChoice(
    /**
     * VREG code.
     */
    val code: Int,
    /**
     * The voltage, mV.
     */
    val millivolts: Int,
    /**
     * A trial of it would raise this unit above 1.20 V now, so `OVERVOLT`
     * must be typed.
     */
    val needsWord: Boolean,
    /**
     * The same for a save (`core_vreg_manual_set`), which does not count a
     * running trial as current.
     */
    val saveNeedsWord: Boolean,
)

/**
 * The flow as a client shows it.
 */
data class VregCalView(
    /**
     * The connection can use the flow: `EXT_CORE_VREG` present, writable,
     * and not refused by a hub. While false with phase `Idle`, hide the
     * flow. While false in another phase the device is away: show the phase.
     */
    val available: Boolean,
    /**
     * Where the flow is.
     */
    val phase: VregCalPhase,
    /**
     * A stable key for `message`, for clients that localise.
     */
    val messageKey: String,
    /**
     * The state or result, stated plainly in English.
     */
    val message: String,
    /**
     * The warning to show before the flow, with the datasheet limits.
     */
    val warning: String,
    /**
     * What a soak does and does not show.
     */
    val soakNote: String,
    /**
     * The voltages offered, lowest first. Empty on a build default the flow
     * does not cover, or before a first status.
     */
    val choices: List<VregChoice>,
    /**
     * What to type when `needs_word` or `commit_needs_word`: `OVERVOLT`,
     * exactly.
     */
    val confirmationWord: String,
    /**
     * `core_vreg_cal_commit` needs the word now, while `phase` is `Passed`.
     * Saving a trial above 1.20 V that is not already stored asks for it, even
     * though it was typed to start the trial: going from RAM to flash is an
     * upward change of its own. Ask again; do not reuse the earlier answer.
     */
    val commitNeedsWord: Boolean,
    /**
     * `core_vreg_manual_set(0, ..)`, the reset to the build default, needs the
     * word now: the unit's current voltage cannot be read from the last
     * status, so nobody can say the reset does not raise it (WP QD28b).
     */
    val resetNeedsWord: Boolean,
    /**
     * The soak to suggest, seconds.
     */
    val defaultSoakS: Long,
    /**
     * The shortest soak accepted, seconds.
     */
    val minSoakS: Long,
    /**
     * The run's or found trial's voltage; 0 if none.
     */
    val targetVreg: Int,
    /**
     * The soak asked for, seconds; 0 if none.
     */
    val soakS: Long,
    /**
     * Seconds of soak counted so far.
     */
    val elapsedS: Long,
    /**
     * The failure shown or on record: its voltage; 0 if none.
     */
    val failedVreg: Int,
    /**
     * Seconds the failed trial ran, if this host saw it start and the record
     * still has the time.
     */
    val ranS: Long?,
    /**
     * The device's uptime when that trial hung; 0 if the record lost it. Its
     * whole run, so at most an upper bound on the trial.
     */
    val uptimeAtHangS: Long,
    /**
     * The next voltage up to offer after that failure; 0 if none.
     */
    val nextVreg: Int,
    /**
     * Nothing above that failure to try: a hardware problem.
     */
    val hardwareProblem: Boolean,
    /**
     * Why the result is unknown (`record_gone`, `not_started`,
     * `trial_changed`); `None` unless `phase` is `Unknown`.
     */
    val unknownReason: String?,
    /**
     * The device stopped answering since the last status: a hang in
     * progress, or a dropped link. The result is still open.
     */
    val linkLost: Boolean,
    /**
     * `core_vreg_cal_start` applies now.
     */
    val canStart: Boolean,
    /**
     * `core_vreg_cal_keep` applies now.
     */
    val canKeep: Boolean,
    /**
     * `core_vreg_cal_commit` applies now.
     */
    val canCommit: Boolean,
    /**
     * The last status read from the device.
     */
    val status: CoreVregInfo?,
    /**
     * Why the last call or read failed, in a sentence; `None` once one
     * succeeded.
     */
    val lastError: String?,
)

/**
 * What a client says about a DSPi Link hub's encryption (owner rule
 * 2026-11-21: by the hub, never "all unencrypted"). Its words are the notice
 * rows [`LinkEncryption::notice_key`] names (`dlink.encryption.*`).
 */
enum class LinkEncryption {
    /**
     * Encrypted, and the hub's key is checked (pinned at pairing).
     */
    VERIFIED,
    /**
     * Encrypted (or will be): the hub offers TLS, its key not pinned yet.
     */
    OFFERED,
    /**
     * Not encrypted: a hub without TLS (Weeb Labs' DSPi Console, the ESP32
     * bridge, an older hub), or met without it.
     */
    OFF,
    /**
     * The hub is this device: nothing crosses the network.
     */
    LOCAL,
    /**
     * Not known yet: a typed address before it answered, no session.
     */
    UNKNOWN,
}

/**
 * Where a Link session is in its life, for the status line.
 */
enum class LinkPhase {
    /**
     * No session.
     */
    IDLE,
    /**
     * The hub wants a PIN.
     */
    NEEDS_PAIRING,
    /**
     * The hub has no device.
     */
    NO_DEVICE,
    /**
     * The hub has several devices: pick one.
     */
    CHOOSE_DEVICE,
    /**
     * Bound to a device.
     */
    BOUND,
    /**
     * Waiting to reconnect.
     */
    RECONNECTING,
    /**
     * Closed by the hub or the client.
     */
    CLOSED,
    /**
     * Refused by the hub.
     */
    REFUSED,
}

/**
 * How healthy an output fill is.
 */
enum class FillBand {
    /**
     * Comfortable.
     */
    GOOD,
    /**
     * Getting close to an edge.
     */
    WARN,
    /**
     * At or past an edge.
     */
    BAD,
}

/**
 * Which protocol generation the open connection's device speaks, as the
 * connect's probe decided it (PLAN-PG section 1.1).
 */
enum class ProtocolGeneration {
    /**
     * Not said: a path that does not report it (a host-supplied transport).
     */
    UNKNOWN,
    /**
     * Firmware 1.1.6 and older: the 1.1.6 opcodes only.
     */
    LEGACY,
    /**
     * Firmware 1.1.7 and later: the paged protocol.
     */
    PAGED,
}

/**
 * How the open device's extension channel is reached (PLAN-PG section 1.3).
 */
enum class ExtEnvelope {
    /**
     * No extension channel (stock firmware).
     */
    NO_CHANNEL,
    /**
     * `REQ_EXTENSION` 0x00 on a 1.1.6-generation device.
     */
    LEGACY,
    /**
     * The tunnel `0xE010` on page `0xE0` of a paged device.
     */
    TUNNEL,
}

/**
 * What kind of device the open connection is (PLAN-PG section 1.9, PGMAT F1).
 * A client shows the screens of the kind only.
 */
enum class DeviceKind {
    /**
     * A DSPi: the bulk image, the DSP model, the generator, the meters.
     */
    DSP,
    /**
     * The alink sender build (`firmware/DSPi-Sender`), on the legacy
     * generation or, dual-stack (FWPG4), on the paged one (WP PGSENDER): a
     * connection with limited capabilities. It has the device info
     * (platform, serial, build), the extension channel with its alink block
     * (`alink_info`, `fetch_alink_*`, `reset_alink_stats`) and the update
     * check's target; no bulk image, no DSP model, no generator, no meters.
     * Every DSP setter answers [`crate::DspiError::Unsupported`] with nothing
     * sent, and `get_state` shows the platform's identity only
     * (`bulk_valid` false, no channels).
     */
    ALINK_SENDER,
}

/**
 * One side of a compare.
 */
enum class AbSide {
    /**
     * The first snapshot (the captured state when none was given).
     */
    A,
    /**
     * The second snapshot.
     */
    B,
}

/**
 * A unit's role in the installation: how the programme reaches it.
 */
enum class InstallationRole {
    /**
     * It plays the audio link from its upstream (a sender, a fan-out or a
     * repeater).
     */
    RECEIVER,
    /**
     * A receiver that also re-emits the stream to the units naming it.
     */
    REPEATER,
    /**
     * It follows an S/PDIF source unit's time base (its upstream).
     */
    SPDIF_FOLLOWER,
    /**
     * USB directly from the host; no upstream.
     */
    USB_DIRECT,
}

/**
 * How a programme reaches the installation
 * ([`InstallationEdit::AddProgrammeSource`]).
 */
enum class InstallationProgrammeKind {
    /**
     * A computer playing to a unit over USB.
     */
    COMPUTER_USB,
    /**
     * A box into a unit's S/PDIF input.
     */
    SPDIF,
    /**
     * An analogue source into a unit's ADC (I2S) input.
     */
    ANALOGUE,
    /**
     * Into the audio link sender's channels.
     */
    ALINK_SENDER,
}

/**
 * One edit of a draft. An `id` left out is made from the name (or the
 * serial); every id an edit names must exist, every serial is in the
 * installation once. JSON: `{"op": "addUnit", "serial": ..., ...}`.
 */
sealed class InstallationEdit {
    /**
     * Add the unit with this serial, in `room`, as `role`, fed by
     * `upstream` (none for a USB-direct unit).
     */
    data class AddUnit(val serial: kotlin.String, val id: kotlin.String?, val name: kotlin.String, val room: kotlin.String?, val role: se.bofr.dspi.core.InstallationRole, val upstream: kotlin.String?) : InstallationEdit()
    /**
     * Remove an element of any kind. What names it as a member (a zone's
     * rooms, a group's units, a unit's room, a zone's source, a source's
     * sender) forgets it, and scene actions aimed at it go; an element it
     * fed is left for the validator to point out.
     */
    data class RemoveElement(val id: kotlin.String) : InstallationEdit()
    /**
     * Rename an element of any kind.
     */
    data class RenameElement(val id: kotlin.String, val name: kotlin.String) : InstallationEdit()
    /**
     * Put a unit in a room, or in none.
     */
    data class SetUnitRoom(val id: kotlin.String, val room: kotlin.String?) : InstallationEdit()
    /**
     * Change a unit's role. The fields the new role cannot have go (a
     * USB-direct unit's upstream, an S/PDIF follower's slots).
     */
    data class SetUnitRole(val id: kotlin.String, val role: se.bofr.dspi.core.InstallationRole) : InstallationEdit()
    /**
     * Set what feeds a unit, and which output of it.
     */
    data class SetUnitUpstream(val id: kotlin.String, val upstream: kotlin.String, val output: kotlin.Int?) : InstallationEdit()
    /**
     * A USB-direct unit's mode and what it does in lock error.
     */
    data class SetUnitUsbMode(val id: kotlin.String, val mode: kotlin.String?, val playUnaligned: kotlin.Boolean) : InstallationEdit()
    /**
     * A unit's speakers by output. A speaker on an output that stays keeps
     * its measured arrival.
     */
    data class SetUnitSpeakers(val id: kotlin.String, val speakers: kotlin.collections.List<se.bofr.dspi.core.InstallationSpeaker>) : InstallationEdit()
    /**
     * Make a unit an S/PDIF time-base source on the output slots of
     * `tx_mask`, or (0) not one.
     */
    data class SetSpdifSource(val id: kotlin.String, val txMask: kotlin.Int) : InstallationEdit()
    /**
     * Add a room.
     */
    data class AddRoom(val id: kotlin.String?, val name: kotlin.String) : InstallationEdit()
    /**
     * Add a zone of `rooms`, playing `source`.
     */
    data class AddZone(val id: kotlin.String?, val name: kotlin.String, val rooms: kotlin.collections.List<kotlin.String>, val source: kotlin.String?) : InstallationEdit()
    /**
     * A zone's rooms.
     */
    data class SetZoneRooms(val id: kotlin.String, val rooms: kotlin.collections.List<kotlin.String>) : InstallationEdit()
    /**
     * Add a group of `units`.
     */
    data class AddGroup(val id: kotlin.String?, val name: kotlin.String, val units: kotlin.collections.List<kotlin.String>) : InstallationEdit()
    /**
     * A group's units.
     */
    data class SetGroupUnits(val id: kotlin.String, val units: kotlin.collections.List<kotlin.String>) : InstallationEdit()
    /**
     * Add a sender (the audio link's clock).
     */
    data class AddSender(val id: kotlin.String?, val name: kotlin.String, val serial: kotlin.String?) : InstallationEdit()
    /**
     * Add a fan-out fed by `upstream`.
     */
    data class AddFanOut(val id: kotlin.String?, val name: kotlin.String, val serial: kotlin.String?, val upstream: kotlin.String, val output: kotlin.Int?) : InstallationEdit()
    /**
     * The installation's own settings; `None` leaves one as it is.
     */
    data class SetSystem(val rateHz: kotlin.Long?, val setD: kotlin.Boolean, val dFrames: kotlin.Int?, val keepUsbAligned: kotlin.Boolean?) : InstallationEdit()
    /**
     * A unit's slots: the audio link channel each of its 8 matrix inputs
     * plays (255 silent); `None` leaves the unit's own table alone. A unit
     * in a zone that plays a source takes the source's slots and no others
     * (a slot clash). Stored: the hub writes them at the next alignment.
     */
    data class SetUnitSlots(val id: kotlin.String, val slots: kotlin.collections.List<kotlin.Int>?) : InstallationEdit()
    /**
     * Add a source: a programme on audio link channels of a sender.
     */
    data class AddSource(val id: kotlin.String?, val name: kotlin.String, val sender: kotlin.String?, val channels: kotlin.collections.List<kotlin.Int>) : InstallationEdit()
    /**
     * A source's sender and channels; the zones playing it are routed again.
     */
    data class SetSource(val id: kotlin.String, val sender: kotlin.String?, val channels: kotlin.collections.List<kotlin.Int>) : InstallationEdit()
    /**
     * What a zone plays. A source routes: every unit of the zone on the
     * audio link takes the source's channels as its slots. `None` stops
     * naming one and leaves the slots as they are.
     */
    data class SetZoneSource(val id: kotlin.String, val source: kotlin.String?) : InstallationEdit()
    /**
     * Add a scene: ops applied at one frame, a `source` op switching a
     * zone's source.
     */
    data class AddScene(val id: kotlin.String?, val name: kotlin.String, val actions: kotlin.collections.List<se.bofr.dspi.core.InstallationSceneAction>, val systemMute: kotlin.Boolean?) : InstallationEdit()
    /**
     * A scene's ops and system mute, replaced.
     */
    data class SetScene(val id: kotlin.String, val actions: kotlin.collections.List<se.bofr.dspi.core.InstallationSceneAction>, val systemMute: kotlin.Boolean?) : InstallationEdit()
    /**
     * Add a programme source: what plays into the installation and where.
     * A description; it routes nothing.
     */
    data class AddProgrammeSource(val id: kotlin.String?, val name: kotlin.String, val kind: se.bofr.dspi.core.InstallationProgrammeKind, val feeds: kotlin.String, val inputs: kotlin.collections.List<kotlin.Int>) : InstallationEdit()
    /**
     * A programme source's kind, what it feeds and its inputs, replaced.
     */
    data class SetProgrammeSource(val id: kotlin.String, val kind: se.bofr.dspi.core.InstallationProgrammeKind, val feeds: kotlin.String, val inputs: kotlin.collections.List<kotlin.Int>) : InstallationEdit()
}

/**
 * Which volume of the units.
 */
enum class SystemVolumeKind {
    /**
     * The listening volume (`vol.user`, -60 to 0 dB).
     */
    USER,
    /**
     * The master volume (`vol.master`, -127 to 0 dB in 0.5 dB steps).
     */
    MASTER,
}

/**
 * Where one unit stands.
 */
enum class SystemVolumeState {
    /**
     * It would be written.
     */
    READY,
    /**
     * It is at the level asked for: nothing to write.
     */
    UNCHANGED,
    /**
     * It may not be, or could not be, written (`code` and `message` say why).
     */
    REFUSED,
    /**
     * Written; `after_db` is what it has now.
     */
    DONE,
}

/**
 * An operation that takes a confirmation token.
 */
enum class ConfirmOp {
    /**
     * Save the live state to a preset slot ([`DspiCore::save_preset_confirmed`]).
     */
    SAVE_PRESET,
    /**
     * Copy a preset ([`DspiCore::copy_preset_confirmed`]).
     */
    COPY_PRESET,
    /**
     * Delete a preset ([`DspiCore::delete_preset_confirmed`]).
     */
    DELETE_PRESET,
    /**
     * Save the live state to the active slot ([`DspiCore::save_params_confirmed`]).
     */
    SAVE_PARAMS,
    /**
     * Factory reset ([`DspiCore::factory_reset_confirmed`]).
     */
    FACTORY_RESET,
    /**
     * Save the output configuration ([`DspiCore::save_output_config_confirmed`]).
     */
    SAVE_OUTPUT_CONFIG,
    /**
     * Restart into the bootloader ([`DspiCore::enter_bootloader_confirmed`]).
     */
    ENTER_BOOTLOADER,
    /**
     * Import a configuration document ([`DspiCore::config_import_confirmed`]).
     */
    CONFIG_IMPORT,
    /**
     * Store a core voltage ([`DspiCore::core_vreg_cal_commit_confirmed`],
     * [`DspiCore::core_vreg_manual_set_confirmed`]).
     */
    VREG_SAVE,
    /**
     * Write a firmware image to the bootloader drive
     * ([`DspiCore::flash_confirmed`]).
     */
    FIRMWARE_FLASH,
}

/**
 * Where a [`FirmwareGuardBoard`]'s voltage came from.
 */
enum class FirmwareGuardBoardSource {
    /**
     * No device was open.
     */
    NO_DEVICE,
    /**
     * The board is in the bootloader, where it cannot be asked.
     */
    BOOTLOADER,
    /**
     * The device was open, but gave no answer that can be believed.
     */
    READ_FAILED,
    /**
     * `EXT_CORE_VREG`.
     */
    EXT_CORE_VREG,
    /**
     * The status block's live voltage, on firmware without `core_vreg`.
     */
    STATUS_BLOCK,
}

/**
 * The guard's answer. Flash only on [`FirmwareGuardVerdict::allowed`].
 */
enum class FirmwareGuardDecision {
    /**
     * The image is not firmware. Confirmation does not help.
     */
    REFUSED,
    /**
     * Blocked until the phrase is typed.
     */
    NEEDS_CONFIRMATION,
    /**
     * There was a risk, and the phrase was typed.
     */
    CONFIRMED,
    /**
     * No known risk.
     */
    CLEAR,
}

/**
 * Why, as a stable key for clients that localise the message.
 */
enum class FirmwareGuardReason {
    /**
     * The image failed the UF2 check.
     */
    IMAGE_INVALID,
    /**
     * No known risk.
     */
    NO_RISK,
    /**
     * At-risk board; the image does not say what voltage it runs at.
     */
    IMAGE_UNKNOWN,
    /**
     * At-risk board; the image is stamped below what the board needs.
     */
    IMAGE_LOWER,
    /**
     * The board's needs are not known.
     */
    BOARD_UNKNOWN,
    /**
     * WP CG14: the image runs above 1.20 V and above the board's current
     * voltage. Its `confirmation_phrase` is the word `OVERVOLT`.
     */
    OVERVOLT,
}

/**
 * Which rule beyond the voltage rule decided an update verdict.
 */
enum class FirmwareUpdateRule {
    /**
     * None: the voltage rule's verdict stands.
     */
    NONE,
    /**
     * The board has no BOOTSEL: refused, whatever is typed.
     */
    NO_BOOTSEL,
    /**
     * Our firmware would give way to an image that may be upstream's.
     */
    LINEAGE_LOSS,
    /**
     * The image is stamped for another kind of device than the target (a
     * DSP image on an alink sender, a sender image on a DSP), or its kind
     * stamp cannot be read: refused, whatever is typed.
     */
    KIND_MISMATCH,
    /**
     * The target is an alink sender and the image does not say what it is
     * for, so it may be a DSP image: asks the typed confirmation.
     */
    KIND_UNKNOWN,
}

/**
 * [`verify_bundled`]'s answer: is this the firmware image the app bundles?
 */
enum class BundledFirmware {
    /**
     * A bundled name, and the bytes are the ones the manifest lists.
     */
    VERIFIED,
    /**
     * Not a bundled name: label it "not a verified firmware image" and
     * keep the usual confirmations. Not a refusal.
     */
    NOT_BUNDLED,
    /**
     * A bundled name (or, before a flash, a bundled image's identity) with
     * other bytes: a mixed-up or damaged copy. Flashing it is refused.
     */
    MISMATCH,
}

/**
 * Where a firmware comes from (PLAN-PG section 1.8): upstream Weeb Labs, or
 * this fork's `bofr-main` (extensions, alink, the 1.20 V core setting, our
 * preset directory).
 */
enum class FirmwareLineage {
    /**
     * Not known: every doubt resolves to "asks".
     */
    UNKNOWN,
    /**
     * Weeb Labs' firmware (stock).
     */
    UPSTREAM,
    /**
     * This fork's `bofr-main`.
     */
    BOFR,
}

/**
 * Which protocol generation a firmware speaks (PLAN-PG section 1.1).
 */
enum class FirmwareGeneration {
    /**
     * Not known.
     */
    UNKNOWN,
    /**
     * 1.1.6 and older: page 0 only.
     */
    LEGACY,
    /**
     * 1.1.7 and later: paged.
     */
    PAGED,
}

/**
 * Where a guarded apply stands ([`GuardedApply::phase`]).
 */
enum class GuardPhase {
    /**
     * None has been begun on this core.
     */
    IDLE,
    /**
     * Applied; waiting for Keep or Revert. The countdown runs.
     */
    WAITING,
    /**
     * Kept: by Keep, or because another console took the device over.
     */
    KEPT,
    /**
     * The settings from before are back.
     */
    REVERTED,
    /**
     * Reverted, but not wholly: some of the settings from before were not
     * put back ([`GuardedApply::notes`] names them). The user must check the
     * settings or restore a backup (a snapshot).
     */
    REVERT_INCOMPLETE,
    /**
     * Putting them back failed; it is not tried again.
     */
    REVERT_FAILED,
    /**
     * The hub went to put them back and the device was not there: nothing
     * was written.
     */
    NOT_WRITTEN,
    /**
     * The connection was lost. With the hub's guard this lasts until the
     * hub says how it ended; without it, the device may still hold the
     * change, and Revert works once the same device is open again.
     */
    LOST,
}

/**
 * Who made a change in the history.
 */
enum class HistorySource {
    /**
     * A write this program asked for.
     */
    LOCAL,
    /**
     * The reversal of an earlier change, sent by [`DspiCore::undo`].
     */
    UNDO,
    /**
     * The repeat of an undone change, sent by [`DspiCore::redo`].
     */
    REDO,
}

/**
 * What a run plays (PLAN-P5 section 1.1, review RC11).
 */
enum class MeasureRunKind {
    /**
     * Log sweeps, one output per cycle round-robin, 2 to 8 passes: responses
     * with phase, arrivals and the timing quality gate.
     */
    WALKED,
    /**
     * One sweep on several outputs at once, each with its polarity (the
     * generator's `invert_mask`): the measured sum of a transition.
     */
    SUMMED,
    /**
     * One sweep on one output (the live view): magnitude only.
     */
    LIVE_SWEEP,
    /**
     * Finite pink noise on one output (at most 60 s): the microphone RTA.
     */
    PINK,
}

/**
 * A way of a loudspeaker, as the user confirmed the layout.
 */
enum class MeasureRole {
    /**
     * A full-range output.
     */
    FULL,
    /**
     * A subwoofer.
     */
    SUB,
    /**
     * The lowest way of a multi-way speaker.
     */
    LOW,
    /**
     * A middle way: needs an active high-pass to be measured (S6).
     */
    MID,
    /**
     * The highest way: needs an active high-pass to be measured (S6).
     */
    HIGH,
}

/**
 * Where the microphone is (owner requirement R3).
 */
enum class MeasurePlacement {
    /**
     * Speakers, the listening position.
     */
    LISTENING_POSITION,
    /**
     * Speakers, 3 to 9 positions averaged (`count`).
     */
    MULTI_POSITION,
    /**
     * Speakers, the microphone close to each driver: one run per output.
     */
    NEAR_FIELD,
    /**
     * Headphones on a coupler, 1 to 9 reseats (`count`).
     */
    HEADPHONES,
}

/**
 * A headphone coupler type.
 */
enum class MeasureCoupler {
    /**
     * An IEC 60318-4 (711-type) ear simulator.
     */
    IEC60318_4,
    /**
     * A flat-plate coupler.
     */
    FLAT_PLATE,
    /**
     * A head and torso simulator or another coupler with pinna.
     */
    HATS,
}

/**
 * Where a session stands.
 */
enum class MeasurePhase {
    /**
     * No session on this core.
     */
    IDLE,
    /**
     * The generator is idle; the microphone's noise floor is taken.
     */
    PRE_ROLL,
    /**
     * The level ramp of one output (S3).
     */
    RAMP,
    /**
     * The run is playing.
     */
    RUN,
    /**
     * The run is analysed, a slice per tick.
     */
    ANALYSING,
    /**
     * Move the microphone (or reseat the headphones), then
     * `measure_next_position`.
     */
    WAIT_POSITION,
    /**
     * The measurement is complete: `measure_result`.
     */
    DONE,
    /**
     * Stopped on a safety rule or by the user: nothing is kept.
     */
    ABORTED,
    /**
     * Stopped and asking the user (the microphone does not hear the output,
     * no signal): nothing is kept.
     */
    FAILED,
}

/**
 * Where the detection stands.
 */
enum class DetectStage {
    /**
     * No detection on this core.
     */
    IDLE,
    /**
     * An output's presence ramp (stage A or A2).
     */
    RAMP,
    /**
     * Its shape above the floor (stage B).
     */
    SHAPE,
    /**
     * Its descent below the floor (C1 or C2).
     */
    DESCENT,
    /**
     * Every output was probed.
     */
    DONE,
    /**
     * It stopped before the end (`issue` says why).
     */
    STOPPED,
}

/**
 * What the live view plays.
 */
enum class MeasureLiveMode {
    /**
     * Short log sweeps, one after the other: one magnitude curve per sweep.
     */
    SWEEP,
    /**
     * Finite pink noise with the microphone RTA (re-armed while live).
     */
    PINK_RTA,
}

/**
 * The microphone RTA's averaging preset.
 */
enum class MeasureRtaAveraging {
    /**
     * Exponential, 125 ms.
     */
    FAST,
    /**
     * Exponential, 1 s.
     */
    SLOW,
    /**
     * Every frame since the start (or the last change) alike.
     */
    INFINITE,
}

/**
 * What made a proposal.
 */
enum class MeasureLiveAdjust {
    /**
     * "Cut this peak".
     */
    CUT_PEAK,
    /**
     * "Fit this range".
     */
    FIT_RANGE,
    /**
     * An edit the client asked to preview.
     */
    EDIT,
}

/**
 * Where the search stands.
 */
enum class MeasureRolloffStage {
    /**
     * No search on this core.
     */
    IDLE,
    /**
     * A segment is being measured (`session` says which phase).
     */
    MEASURING,
    /**
     * The search ended with a result.
     */
    DONE,
    /**
     * It stopped without a result (`issue` says why).
     */
    STOPPED,
}

/**
 * Why the search ended.
 */
enum class MeasureRolloffEnd {
    /**
     * The response fell [`ROLLOFF_STOP_DB`] below its loudest point.
     */
    ROLLED_OFF,
    /**
     * The output's floor was reached first (1 kHz on a tweeter).
     */
    FLOOR,
}

/**
 * Where a system measurement is.
 */
enum class MeasureSystemPhase {
    /**
     * No session.
     */
    IDLE,
    /**
     * The noise floor is captured (nothing plays).
     */
    PRE_ROLL,
    /**
     * One output's ramp step plays (S3).
     */
    RAMP,
    /**
     * The timed run plays.
     */
    RUN,
    /**
     * The capture is analysed.
     */
    ANALYSING,
    /**
     * Finished: a result (or a summed check's verdicts) is ready.
     */
    DONE,
    /**
     * Stopped: by the user, a safety rule or the hub; nothing kept.
     */
    ABORTED,
    /**
     * Could not finish (no signal, the gate, the ramp); nothing kept.
     */
    FAILED,
}

/**
 * What a session's runs are for.
 */
enum class MeasureSystemPurpose {
    /**
     * The walked measurement.
     */
    MEASURE,
    /**
     * The summed check of every inter-unit transition (RC5f).
     */
    SUM_CHECK,
    /**
     * The summed runs repeated after an apply (P5's verify).
     */
    VERIFY,
}

/**
 * Where an applied system alignment stands.
 */
enum class MeasureSystemApplyStage {
    /**
     * Nothing applied.
     */
    NONE,
    /**
     * Applied; the summed runs are to be repeated (`measure_system_verify`).
     */
    APPLIED,
    /**
     * Verified (or not): Keep or Revert.
     */
    VERIFIED,
    /**
     * Kept.
     */
    KEPT,
    /**
     * Reverted: the model and the units are as filed.
     */
    REVERTED,
    /**
     * The revert (the user's, or the hub's guard's) did not put everything
     * back: the model was not set back, a unit's write failed, a delay
     * reads back other than filed, or what the hub did is not known.
     * `revert_notice` is the `revert.*` notice and `message` names what;
     * the user must check the settings or restore a backup (a snapshot).
     */
    REVERT_INCOMPLETE,
}

/**
 * What a write changes.
 */
enum class MeasureTuneKind {
    /**
     * A crossover corner.
     */
    CROSSOVER,
    /**
     * An output delay.
     */
    DELAY,
    /**
     * The net polarity of an output's feeding crosspoints.
     */
    POLARITY,
    /**
     * An output gain (a way's level, cut only).
     */
    LEVEL,
    /**
     * An output gain cut for the EQ's boost.
     */
    HEADROOM,
    /**
     * A PEQ band.
     */
    EQ,
}

/**
 * Where the summed check stands.
 */
enum class MeasureTuneCheck {
    /**
     * The proposal has no timing write: nothing to check.
     */
    NOT_NEEDED,
    /**
     * Not run yet: the timing writes cannot be applied.
     */
    PENDING,
    /**
     * Every checked transition passed.
     */
    PASSED,
    /**
     * A transition failed: its speaker's timing writes are withdrawn.
     */
    FAILED,
}

/**
 * Where a tune stands.
 */
enum class MeasureTuneStage {
    /**
     * No tune on this core.
     */
    IDLE,
    /**
     * A proposal waits to be checked or applied.
     */
    PROPOSED,
    /**
     * The summed runs play.
     */
    SUM_CHECK,
    /**
     * Applied inside the guard: verify, Keep or Revert.
     */
    APPLIED,
    /**
     * The verify runs play (inside the guard).
     */
    VERIFYING,
    /**
     * Verified (inside the guard): Keep or Revert.
     */
    VERIFIED,
    /**
     * Kept: the A/B compare may be started.
     */
    KEPT,
    /**
     * Reverted (by the user, the timeout or a failed write).
     */
    REVERTED,
    /**
     * The guard ended without putting everything back (part of it, nothing,
     * or it is not known): `issue` holds the `revert.*` notice and what was
     * not put back. The user must check the settings or restore a backup
     * (a snapshot): the "before" snapshot is `snapshot_before_id`.
     */
    REVERT_INCOMPLETE,
}

/**
 * How a notice is shown.
 */
enum class NoticeKind {
    /**
     * Nothing went wrong; something to know.
     */
    INFO,
    /**
     * Not done, for a reason the user can change or wait out.
     */
    WARNING,
    /**
     * Not done: something failed.
     */
    ERROR,
}

/**
 * A function that can hold a GPIO. The C ABI passes it as its code (the
 * number in brackets).
 */
enum class PinFunctionKind {
    /**
     * (0) A physical output, `index` 0..`num_pin_outputs`: the S/PDIF or
     * I2S slots, then the PDM subwoofer last.
     */
    OUTPUT,
    /**
     * (1) The I2S bit clock of the master (or unified) pair; also holds
     * LRCLK, BCK + 1.
     */
    I2S_BCK,
    /**
     * (2) The slave pair's bit clock (split clock-pin mode); also its LRCLK.
     */
    I2S_BCK_SLAVE,
    /**
     * (3) The I2S master clock.
     */
    MCK,
    /**
     * (4) An S/PDIF receiver, `index` 0..3.
     */
    SPDIF_RX,
    /**
     * (5) An I2S input data pin, `index` = stereo pair 0..3.
     */
    I2S_RX,
    /**
     * (6) The ADAT output (RP2350).
     */
    ADAT_OUT,
    /**
     * (7) The ADAT input (RP2350).
     */
    ADAT_IN,
    /**
     * (8) The DAC hardware mute line.
     */
    DAC_MUTE,
    /**
     * (9) The UART control interface's TX.
     */
    UART_TX,
    /**
     * (10) Its RX.
     */
    UART_RX,
    /**
     * (11) The I2C control interface's SDA.
     */
    I2C_SDA,
    /**
     * (12) Its SCL.
     */
    I2C_SCL,
    /**
     * (13) A control-surface binding, `index` = its slot.
     */
    CONTROL_SURFACE,
}

/**
 * What a held GPIO is doing, for grouping (the Console's five roles).
 */
enum class PinHolderRole {
    /**
     * A physical or ADAT output.
     */
    OUTPUT,
    /**
     * An I2S clock.
     */
    CLOCK,
    /**
     * An audio input.
     */
    INPUT,
    /**
     * A control interface or control surface.
     */
    CONTROL,
    /**
     * The DAC mute.
     */
    UTILITY,
}

/**
 * Why a pin was refused.
 */
enum class PinRefusalReason {
    /**
     * This platform's pins are fixed (STM32H723, or a platform this build
     * does not know).
     */
    NOT_ASSIGNABLE,
    /**
     * The device has no such function (an output, input or pair past its
     * count; ADAT on an RP2040; a feature its firmware lacks).
     */
    NO_SUCH_FUNCTION,
    /**
     * Not a GPIO this platform allows (23-25 are power and LED; BCK also
     * needs BCK + 1).
     */
    INVALID_PIN,
    /**
     * A GPIO, but not one this function's peripheral can use: MCK off a
     * clock-output pin, UART or I2C off its mux position or instance.
     */
    WRONG_MUX,
    /**
     * Another function holds it: see `holder`.
     */
    IN_USE,
    /**
     * The function cannot move now: MCK while enabled, the I2S clock pair
     * while I2S outputs run on it.
     */
    OUTPUT_ACTIVE,
    /**
     * The ADAT input's pin cannot be cleared while the input is enabled.
     */
    CLEAR_WHILE_ENABLED,
}

/**
 * Where a row's role comes from.
 */
enum class RoleSource {
    /**
     * The user set or confirmed it.
     */
    USER,
    /**
     * The speaker detection found it.
     */
    DETECTED,
    /**
     * A suggestion (the filters' inference, an import), nobody's word.
     */
    SUGGESTED,
    /**
     * Set by an AI agent from the user's words (the layout's `stated`),
     * not checked by the user.
     */
    STATED,
}

/**
 * How far the layout can be trusted ([`SpeakerLayout::state`]).
 */
enum class LayoutState {
    /**
     * Nobody's word: no roles reach the safety rules.
     */
    UNCONFIRMED,
    /**
     * Found by the speaker detection, not yet confirmed: its roles guard the
     * outputs as a confirmed layout's do.
     */
    AUTO_DETECTED,
    /**
     * The user confirmed it.
     */
    CONFIRMED,
    /**
     * Set by an AI agent from the user's words, not yet confirmed: its
     * roles guard the outputs as a detected layout's do, an output it does
     * not name is unknown (a tweeter), and an agent's sub-floor stimulus on
     * a stated non-tweeter waits for the top-fall check.
     */
    STATED,
}

/**
 * What the speaker detection made of an output.
 */
enum class DetectClass {
    /**
     * A tweeter, or anything that plays flat to 20 kHz and is not probed
     * lower (a full-range driver, a dome midrange): role high.
     */
    TWEETER,
    /**
     * Rolls off between 70 and 200 Hz: role mid.
     */
    MIDRANGE,
    /**
     * Plays below 70 Hz and above 1 kHz: role low.
     */
    WOOFER,
    /**
     * Plays below 70 Hz, 20 dB or more quieter at 1 to 2 kHz: role sub.
     */
    SUB,
    /**
     * A full-range driver: the user's correction only, never detected.
     */
    FULL_RANGE,
    /**
     * Nothing reached the microphone: left out of the layout.
     */
    NOTHING,
    /**
     * The probe did not finish it (stopped, the microphone did not follow,
     * the settings changed): role high.
     */
    UNKNOWN,
    /**
     * The output was off or muted: not probed.
     */
    OFF,
}

/**
 * How sure the detection is of a class.
 */
enum class DetectConfidence {
    /**
     * The evidence is plain.
     */
    HIGH,
    /**
     * Probably ("Tweeter?": flat to 20 kHz, could be a full-range driver).
     */
    MEDIUM,
    /**
     * Uncertain, treated as the most protective class.
     */
    LOW,
}

/**
 * Where the detection first heard an output.
 */
enum class DetectHeard {
    /**
     * In the presence band, 4 to 16 kHz (stage A).
     */
    TOP,
    /**
     * Between the floor and 4 kHz (stage A2).
     */
    ABOVE_FLOOR,
    /**
     * Only by the shaped probe below the floor (stage C1).
     */
    BELOW_FLOOR,
    /**
     * Nowhere.
     */
    NEVER,
}

/**
 * What the top-fall check (the detection's stage B) made of a stated
 * non-tweeter, before an agent plays anything below its floor.
 */
enum class RoleCheckVerdict {
    /**
     * The top end falls as a woofer's or a midrange's does: the stated
     * role stands.
     */
    TOP_FALLS,
    /**
     * Nothing heard above the floor, but heard below it by the
     * detection's shaped probe (at most −50 dBFS, two octaves): a sub or a
     * low woofer, no tweeter; the stated role stands. (Heard nowhere, the
     * check is [`RoleCheckVerdict::Unfinished`].)
     */
    SILENT,
    /**
     * The top holds like a tweeter's: nothing below the floor plays on it
     * for an agent, and the safety rules take it for a tweeter.
     */
    TOP_HOLDS,
    /**
     * The check did not finish (stopped, the microphone did not follow):
     * still unchecked.
     */
    UNFINISHED,
}

/**
 * Where a run is: [`VregCalView::phase`]. The details are in the view.
 */
enum class VregCalPhase {
    /**
     * The flow is not open.
     */
    IDLE,
    /**
     * Open: show the warning and what the device has on record.
     */
    REVIEW,
    /**
     * Clearing the device's record before the trial.
     */
    CLEARING,
    /**
     * The trial was sent and is not seen running yet.
     */
    STARTING_TRIAL,
    /**
     * The trial runs; the soak is counting. Abort is available.
     */
    SOAKING,
    /**
     * Passed: the trial still runs and nothing is saved. Commit or end.
     */
    PASSED,
    /**
     * The trial hung: `failed_vreg`, `ran_s`, `next_vreg`, `hardware_problem`.
     */
    FAILED,
    /**
     * The result cannot be known: run again.
     */
    UNKNOWN,
    /**
     * A trial nobody here started is running: end or keep.
     */
    TRIAL_FOUND,
    /**
     * A kept trial outside the flow's range: left alone, cannot pass.
     */
    TRIAL_LEFT_RUNNING,
    /**
     * Ending the trial.
     */
    ENDING,
    /**
     * The trial ended.
     */
    ENDED,
    /**
     * Saving: waiting to read the voltage back.
     */
    COMMITTING,
    /**
     * Saved and read back.
     */
    COMMITTED,
    /**
     * A save or an end did not show in time. Nothing was retried.
     */
    VERIFY_FAILED,
}

/**
 * What can happen to the demo device: [`DspiCore::core_vreg_demo_event`].
 */
enum class VregDemoEvent {
    /**
     * The watchdog fires.
     */
    HANG,
    /**
     * A requested reboot: no failure on record.
     */
    REBOOT,
    /**
     * Power lost: every record gone.
     */
    POWER_CYCLE,
    /**
     * `seconds` pass on the device's clock.
     */
    ADVANCE_UPTIME,
}

/**
 * A parameter value: `dspi_proto::value::Value` across the bindings. In
 * JSON (the C ABI, the web binding) it is tagged by kind in lower case:
 * `{"float": -12.5}`, `{"bool": true}`, `{"bytes": [1, 2]}`, `"trigger"`.
 */
sealed class ParamValue {
    /**
     * A yes/no value.
     */
    data class Bool(val v1: kotlin.Boolean) : ParamValue()
    /**
     * A number.
     */
    data class Float(val v1: kotlin.Float) : ParamValue()
    /**
     * A whole number.
     */
    data class Int(val v1: kotlin.Long) : ParamValue()
    /**
     * A choice, as its wire number (the registry has the labels).
     */
    data class Choice(val v1: kotlin.Int) : ParamValue()
    /**
     * A bit mask.
     */
    data class Mask(val v1: kotlin.Long) : ParamValue()
    /**
     * Text.
     */
    data class Text(val v1: kotlin.String) : ParamValue()
    /**
     * A structured payload, as the registry's packet encodes it.
     */
    data class Bytes(val v1: kotlin.collections.List<kotlin.Int>) : ParamValue()
    /**
     * An action with no value.
     */
    data object Trigger : ParamValue()
}

/**
 * A rebuild running on the core's threads. Poll it from a UI timer; dropping it
 * cancels it, without waiting for the requests in flight.
 */
interface AutoEqRebuild : AutoCloseable {
    /**
     * The newest progress. Does not block.
     */
    fun poll(): AutoEqRebuildProgress
    /**
     * Stop at the next batch of profiles; nothing is written. Does not block:
     * keep polling until `finished`.
     */
    fun cancel()
}

/**
 * A secret the hub made and shows once: an API key, a webhook's secret. An
 * object, not a string field, so that no binding's generated record
 * printing (Kotlin `toString`, Swift `description`) shows it: read it with
 * [`HubSecret::reveal`] to show it once, and keep it nowhere else. Its
 * `Debug` is `set`; serialized (the C and wasm answers) it is the plain
 * string.
 */
interface HubSecret : AutoCloseable {
    /**
     * The secret's text, to show once. No I/O.
     */
    fun reveal(): String
}
